insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('lamps-on-at-four-dark-evenings-routine-sheet', 'Lamps On at Four Dark Evenings Routine Sheet', 'worksheet'::resource_kind, 'A routine for the weeks when it is dark before dinner, built around light, one anchor activity and a set bedtime.', 'Use it to give a client a shape for the long evenings instead of a slide from dusk to bed.', array['Adults', 'Teens']::text[], '20 minutes, then nightly for two weeks', 'Ask the client what the hours between sunset and bed look like now, honestly, and write them in the first box. Then build the evening from the outside in: which lamps go on and when, one thing they do with their hands or feet before screens, who they might hear from, and a lights-out time they can keep most nights. Watch for a plan with six items; two anchors kept beat six abandoned. Review after two weeks and keep only what happened.', '[{"id": "f0", "type": "textarea", "label": "What my evenings look like now, from sunset to bed:"}, {"id": "f1", "type": "textarea", "label": "The lamps or lights I will turn on, and when:"}, {"id": "f2", "type": "textarea", "label": "One thing I will do with my hands or feet before any screen:"}, {"id": "f3", "type": "textarea", "label": "A person I could hear from or reach out to on two of the evenings:"}, {"id": "f4", "type": "textarea", "label": "My lights-out time, and what I do in the last fifteen minutes:"}, {"id": "f5", "type": "textarea", "label": "After two weeks: what actually happened, and what I will keep:"}]'::jsonb, array['routines', 'planning', 'winter']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('overflowing-junk-drawer-one-drawer-reset-sheet', 'Overflowing Junk Drawer One Drawer Reset Sheet', 'worksheet'::resource_kind, 'A single-drawer tidy used as a small, finishable task when the whole house feels like too much.', 'Use it to give a client one contained win and a look at how they talk to themselves while doing it.', array['Adults', 'Teens']::text[], '30 minutes', 'Pick the one drawer or shelf the client names as the worst, set a timer for twenty minutes, and have them sort into keep, move and toss without leaving the room. The sheet asks them to notice the thoughts that showed up midway, which is where the material usually is: the urge to quit, the old guilt, the jump to the rest of the house. Keep the task to one drawer even if they want to go on; stopping while ahead is the point.', '[{"id": "f0", "type": "textarea", "label": "The drawer or shelf I chose, and why that one:"}, {"id": "f1", "type": "textarea", "label": "What I kept, what I moved, what I tossed:"}, {"id": "f2", "type": "textarea", "label": "The thoughts that showed up about ten minutes in:"}, {"id": "f3", "type": "textarea", "label": "How I felt when the timer went off:"}, {"id": "f4", "type": "textarea", "label": "What stopping at one drawer was like for me:"}]'::jsonb, array['planning', 'self-monitoring', 'behavioral activation']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('tax-documents-folder-start-in-december-sheet', 'Tax Documents Folder Start in December Sheet', 'worksheet'::resource_kind, 'A December head start on the paperwork that usually arrives as an April panic, one folder and a short list.', 'Use it to turn a yearly dread into a small sorting task started early.', array['Adults']::text[], '20 minutes, then five minutes a week', 'For a client who describes tax season as a wall of avoidance every spring, start now: one physical or digital folder, a list of the documents they expect, and a weekly five-minute drop-in. The sheet separates what they can gather today from what has to arrive in the mail. Watch for the client who wants to understand the whole return before filing a single receipt; the folder is for collecting, not deciding.', '[{"id": "f0", "type": "textarea", "label": "Where my folder lives, paper or digital:"}, {"id": "f1", "type": "textarea", "label": "Documents I already have and can put in it today:"}, {"id": "f2", "type": "textarea", "label": "Documents that will arrive later, and roughly when:"}, {"id": "f3", "type": "textarea", "label": "My five-minute weekly check-in time:"}, {"id": "f4", "type": "textarea", "label": "What I will tell myself when the April worry starts early:"}]'::jsonb, array['planning', 'avoidance', 'money']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('nagging-small-home-repairs-one-a-week-sheet', 'Nagging Small Home Repairs One a Week Sheet', 'worksheet'::resource_kind, 'A list of the small broken things around the house and a plan to fix exactly one each week.', 'Use it to stop the drip of low-grade irritation from a dozen small undone jobs.', array['Adults', 'Couples']::text[], '15 minutes, then weekly', 'Have the client walk the house in their mind and list every small thing that is broken, loose, chirping or stuck. Then they pick the one that bothers them most per day of exposure, not the hardest, and schedule it for this week. The sheet tracks four weeks. The talk afterward is often about why the list grew so long, and what else in the client''s life waits in the same way; let that come from them.', '[{"id": "f0", "type": "textarea", "label": "Everything small that is broken, loose, chirping or stuck:"}, {"id": "f1", "type": "textarea", "label": "The one that bothers me most often, and when I will fix it this week:"}, {"id": "f2", "type": "textarea", "label": "What I need to buy or borrow for it:"}, {"id": "f3", "type": "textarea", "label": "Week by week: which one I fixed and how long it really took:"}, {"id": "f4", "type": "textarea", "label": "What I notice about why the list got this long:"}]'::jsonb, array['planning', 'behavioral activation', 'routines']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('reconnecting-with-an-old-friend-first-message-draft-sheet', 'Reconnecting With an Old Friend First Message Draft Sheet', 'worksheet'::resource_kind, 'A drafting sheet for the first message to a friend the client has not spoken to in years, short and without apology.', 'Use it to get a client past the blank screen and the pull to explain the silence.', array['Adults', 'Teens']::text[], '20 minutes', 'The client names the friend, what they remember liking about them, and the reason the contact lapsed, said once and plainly. Then they draft a message of three sentences or fewer: a hello, one specific memory or question, and an easy out. Cross out every apology and every explanation of the gap; most old friends do not want one. Decide together what a no-reply would mean and would not mean before they send it.', '[{"id": "f0", "type": "textarea", "label": "The friend, and what I liked about them:"}, {"id": "f1", "type": "textarea", "label": "Why we lost touch, in one honest line:"}, {"id": "f2", "type": "textarea", "label": "My three-sentence draft:"}, {"id": "f3", "type": "textarea", "label": "The apologies and explanations I crossed out:"}, {"id": "f4", "type": "textarea", "label": "If they do not reply, what that means and does not mean:"}]'::jsonb, array['connection', 'communication', 'avoidance']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('magnification-of-the-typo-in-the-sent-report-sheet', 'Magnification of the Typo in the Sent Report Sheet', 'cbt'::resource_kind, 'A thinking-trap sheet for the one typo in a sent document that grew into a verdict on the client''s competence.', 'Use it to put a small mistake back to its real size next to the rest of the work.', array['Adults', 'Teens']::text[], '15 minutes', 'Start with the facts: what the error was, who could have seen it, and what has actually happened since. Then have the client rate the mistake on a line from zero to one hundred against other work errors they can think of, their own and others''. The gap between the felt size and the rated size is the magnification. Finish with what they would say to a colleague who sent the same typo; the double standard usually shows itself.', '[{"id": "f0", "type": "textarea", "label": "The mistake, exactly as it was:"}, {"id": "f1", "type": "textarea", "label": "What I told myself it meant about me:"}, {"id": "f2", "type": "textarea", "label": "Who could have seen it, and what has actually happened since:"}, {"id": "f3", "type": "textarea", "label": "Where it sits on a zero to one hundred line of work mistakes I know of:"}, {"id": "f4", "type": "textarea", "label": "What I would say to a colleague who did the same:"}, {"id": "f5", "type": "textarea", "label": "A sentence that fits the real size of it:"}]'::jsonb, array['thinking traps', 'core CBT', 'self-criticism']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('arriving-exactly-on-time-not-early-experiment-sheet', 'Arriving Exactly on Time Not Early Experiment Sheet', 'cbt'::resource_kind, 'An experiment for the client who arrives thirty minutes early everywhere, testing what happens when they arrive on the dot.', 'Use it to test the prediction that being merely on time brings disaster or disapproval.', array['Adults', 'Teens']::text[], 'One week', 'Pick two low-stakes appointments this week and have the client plan to arrive within two minutes of the start time. Write the prediction first: what exactly will go wrong and how sure they are. Afterward they record what happened and re-rate the belief. Watch for safety behaviors, like sitting in the parking lot for twenty minutes and counting that as on time; the experiment is about the waiting, not the clock.', '[{"id": "f0", "type": "textarea", "label": "The two appointments I will arrive at on time this week:"}, {"id": "f1", "type": "textarea", "label": "What I predict will happen, and how sure I am (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "What I usually do with the early time, and what it protects me from:"}, {"id": "f3", "type": "textarea", "label": "What actually happened at each one:"}, {"id": "f4", "type": "textarea", "label": "How sure I am of the prediction now, and what I will try next:"}]'::jsonb, array['behavioral experiment', 'core CBT', 'predictions']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('downward-arrow-on-being-left-off-the-meeting-invite-sheet', 'Downward Arrow on Being Left Off the Meeting Invite Sheet', 'cbt'::resource_kind, 'A downward arrow from a missing calendar invite to the belief underneath about belonging and worth.', 'Use it to trace a small workplace sting to the core belief it landed on.', array['Adults']::text[], '25 minutes', 'Begin with the hot thought about the invite and ask, repeatedly, if that were true what would it mean about you. Write each answer on its own line until the client reaches a statement that feels like bedrock, usually about being dispensable or not belonging. Do this in session; the bottom rungs can be heavy. Then go back up the ladder and mark which rungs have any evidence at all and which were assumed.', '[{"id": "f0", "type": "textarea", "label": "The situation: the meeting I was not invited to:"}, {"id": "f1", "type": "textarea", "label": "My first thought about it:"}, {"id": "f2", "type": "textarea", "label": "If that were true, it would mean..."}, {"id": "f3", "type": "textarea", "label": "And if that were true, it would mean..."}, {"id": "f4", "type": "textarea", "label": "The belief at the bottom of the arrow:"}, {"id": "f5", "type": "textarea", "label": "Which rungs on the way down had evidence, and which I assumed:"}]'::jsonb, array['core beliefs', 'core CBT', 'work']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('i-must-never-inconvenience-anyone-belief-evidence-sheet', 'I Must Never Inconvenience Anyone Belief Evidence Sheet', 'cbt'::resource_kind, 'An evidence sheet for the rule that asking anything of anyone is an imposition, with a test of the rule''s cost.', 'Use it to loosen a rule that keeps a client from asking, delegating or being helped.', array['Adults', 'Teens']::text[], '20 minutes', 'Write the rule in the client''s own words at the top, then gather evidence for and against it from the last month, including times other people inconvenienced them and what they actually felt about it. Add a cost column: what the rule has made them carry alone. Finish with a softer rule they could try for a week. Watch for evidence against being dismissed as exceptions; ask how many exceptions it takes before a rule changes.', '[{"id": "f0", "type": "textarea", "label": "The rule, in my words:"}, {"id": "f1", "type": "textarea", "label": "Evidence from this month that the rule is true:"}, {"id": "f2", "type": "textarea", "label": "Evidence from this month that it is not, including times I was glad to be asked:"}, {"id": "f3", "type": "textarea", "label": "What the rule has cost me:"}, {"id": "f4", "type": "textarea", "label": "A softer version of the rule I will try for one week:"}]'::jsonb, array['core beliefs', 'core CBT', 'boundaries']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('activity-schedule-for-a-gray-december-weekend-sheet', 'Activity Schedule for a Gray December Weekend Sheet', 'cbt'::resource_kind, 'An hour-by-hour activity schedule for a dark weekend with nothing planned, rated for pleasure and accomplishment.', 'Use it to put a few chosen activities into the empty hours before low mood fills them.', array['Adults', 'Teens']::text[], '20 minutes, then the weekend', 'Lay out Saturday and Sunday in two-hour blocks and have the client place three things they have chosen on purpose: one for pleasure, one for a sense of accomplishment, one with another person. The rest can stay blank. After the weekend they rate each block for pleasure and accomplishment from zero to ten. The surprise is often that the planned blocks were not the best ones, which is worth a conversation about what actually lifted the hour.', '[{"id": "f0", "type": "textarea", "label": "Saturday in two-hour blocks, with my three chosen activities placed:"}, {"id": "f1", "type": "textarea", "label": "Sunday in two-hour blocks, with my three chosen activities placed:"}, {"id": "f2", "type": "textarea", "label": "What I predict the pleasure and accomplishment ratings will be:"}, {"id": "f3", "type": "textarea", "label": "The actual ratings for each block after the weekend:"}, {"id": "f4", "type": "textarea", "label": "The block that surprised me, and why:"}]'::jsonb, array['behavioral activation', 'core CBT', 'planning']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('thoughts-as-price-tags-hanging-off-everything-page', 'Thoughts as Price Tags Hanging Off Everything Page', 'act'::resource_kind, 'A defusion page that pictures the mind''s judgments as price tags it hangs on every person, plan and object.', 'Use it to help a client notice evaluation as a habit of mind rather than a property of things.', array['Adults', 'Teens']::text[], '15 minutes', 'Walk through a recent ordinary hour and have the client list the tags the mind hung on things: a cheap tag on their own work, an overpriced one on a stranger''s confidence, a clearance sticker on the weekend. The exercise is not to re-price but to see the tagging itself. Then practice with the room you are in: name the tag, say thank you mind, and look at the object again. Watch for the client who wants to argue with the prices; that is still shopping.', '[{"id": "f0", "type": "textarea", "label": "An ordinary hour this week, and the price tags my mind hung on things in it:"}, {"id": "f1", "type": "textarea", "label": "The tag I hung on myself most often:"}, {"id": "f2", "type": "textarea", "label": "What I notice when I read the tag as a tag instead of a fact:"}, {"id": "f3", "type": "textarea", "label": "Three objects in this room and the tags my mind puts on them:"}, {"id": "f4", "type": "textarea", "label": "What I did after saying thank you mind and looking again:"}]'::jsonb, array['defusion', 'core ACT', 'metaphor']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('values-at-the-pharmacy-pickup-counter-page', 'Values at the Pharmacy Pickup Counter Page', 'act'::resource_kind, 'A values page for the slow line at the pharmacy counter, where irritation and impatience show what matters underneath.', 'Use it to turn a weekly wait into a place to practice acting on a value.', array['Adults']::text[], '10 minutes, then the next wait', 'Ask the client what they feel in that line and what they usually do with it: the phone, the sighing, the glance at the person ahead. Then ask what they would want to be about in that moment if someone they respect were watching. Patience is rarely the answer; it is usually kindness, dignity or calm. Pick one small act that fits the value for the next wait and have them record what it was like. Keep the stakes low; the pharmacy is just a practice court.', '[{"id": "f0", "type": "textarea", "label": "What I feel in that line, and what I usually do with it:"}, {"id": "f1", "type": "textarea", "label": "If someone I respect were watching, what would I want to be about there?"}, {"id": "f2", "type": "textarea", "label": "One small act in the line that fits that value:"}, {"id": "f3", "type": "textarea", "label": "What it was like to do it:"}, {"id": "f4", "type": "textarea", "label": "Where else that same value is waiting for me this week:"}]'::jsonb, array['values', 'core ACT', 'committed action']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('willing-to-ask-the-question-twice-page', 'Willing to Ask the Question Twice Page', 'act'::resource_kind, 'A willingness page for asking someone to repeat or explain themselves a second time instead of nodding and guessing.', 'Use it to make room for the small embarrassment of not having understood the first time.', array['Adults', 'Teens']::text[], '15 minutes', 'Most clients who nod along are protecting themselves from a few seconds of looking slow. Have them name the feeling they would have to make room for, where it sits in the body, and what they lose by guessing instead. Then they choose three low-stakes moments this week to ask twice, and after each note the feeling''s size and what the other person actually did. The page is about carrying the discomfort, not about becoming someone who never misses a word.', '[{"id": "f0", "type": "textarea", "label": "The feeling I would have to make room for when I ask twice, and where it sits in my body:"}, {"id": "f1", "type": "textarea", "label": "What guessing instead has cost me:"}, {"id": "f2", "type": "textarea", "label": "Three low-stakes moments this week where I will ask again:"}, {"id": "f3", "type": "textarea", "label": "After each one: how big the feeling got, and what the person did:"}, {"id": "f4", "type": "textarea", "label": "What asking twice says about what I care about:"}]'::jsonb, array['willingness', 'core ACT', 'communication']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('kettle-coming-to-a-boil-present-moment-page', 'Kettle Coming to a Boil Present Moment Page', 'act'::resource_kind, 'A present-moment practice built around the two minutes a kettle takes to boil, done with no phone in hand.', 'Use it to give a client a daily contact-with-now practice that is already in their routine.', array['Adults', 'Teens']::text[], 'Two minutes daily', 'The client fills the kettle and then does nothing else until it clicks off: sound, steam, the change in pitch, the feet on the floor. When the mind leaves for the inbox or the argument, they notice where it went and return to the sound. The page asks them to record three boils this week, not to describe calm but to describe what the mind did. Clients who find two minutes unbearable have told you something useful about their day.', '[{"id": "f0", "type": "textarea", "label": "Three boils this week, and where my mind went during each:"}, {"id": "f1", "type": "textarea", "label": "The sound or sight I kept coming back to:"}, {"id": "f2", "type": "textarea", "label": "How the two minutes felt on the day I least wanted to stand there:"}, {"id": "f3", "type": "textarea", "label": "What my mind said about standing still doing nothing:"}, {"id": "f4", "type": "textarea", "label": "Another two-minute wait in my day I could use the same way:"}]'::jsonb, array['mindfulness', 'core ACT', 'routines']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('passengers-on-the-bus-with-holiday-shopping-bags-page', 'Passengers on the Bus With Holiday Shopping Bags Page', 'act'::resource_kind, 'A seasonal passengers-on-the-bus page where the loud riders are the December shoulds, comparisons and bills.', 'Use it to help a client keep driving toward what the season is for while the passengers shout.', array['Adults']::text[], '20 minutes', 'Have the client name the passengers who board in December: the one with the perfect-gift list, the one tallying what everyone else is spending, the one who says the family will be disappointed again. Give each a seat and a line. Then ask where the client wants the bus to go this season, in their own words, and what the passengers would make them do if they drove. The practice is letting them ride along, loud bags and all, while the route stays the client''s.', '[{"id": "f0", "type": "textarea", "label": "The passengers who board my bus in December, and what each one shouts:"}, {"id": "f1", "type": "textarea", "label": "What I usually do when they get loud: stop, argue, turn around?"}, {"id": "f2", "type": "textarea", "label": "Where I want this season''s bus to go, in my words:"}, {"id": "f3", "type": "textarea", "label": "One stretch of road this week where I will drive with them still aboard:"}, {"id": "f4", "type": "textarea", "label": "What happened on that stretch:"}]'::jsonb, array['metaphor', 'core ACT', 'values']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('mindfulness-of-current-emotion-while-folding-towels-card', 'Mindfulness of Current Emotion While Folding Towels Card', 'dbt'::resource_kind, 'A mindfulness of current emotion card paired with a basket of laundry, so the feeling is observed while the hands work.', 'Use it to let a client experience a wave of emotion with the hands occupied and the feet on the floor.', array['Adults', 'Teens']::text[], 'Ten minutes', 'Teach the skill with the laundry already there: as the client folds, they name the emotion present, find where it sits in the body, and describe it as a wave, noticing when it rises and when it eases, without pushing it along. The towels give the hands something and the rhythm a count. Have them practice once with a mild emotion before they try it with a strong one. Watch for folding becoming a distraction; the attention goes to the feeling, the hands keep the rhythm.', '[{"id": "f0", "type": "textarea", "label": "The emotion I noticed while I folded, and where it sat in my body:"}, {"id": "f1", "type": "textarea", "label": "What the wave did while I worked: rose, held, eased?"}, {"id": "f2", "type": "textarea", "label": "The urge that came with it, and what I did with the urge:"}, {"id": "f3", "type": "textarea", "label": "What my mind said about the feeling, and whether I got pulled into that:"}, {"id": "f4", "type": "textarea", "label": "How the feeling was different by the last towel:"}]'::jsonb, array['emotion regulation', 'core DBT', 'mindfulness']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('nonjudgmental-stance-toward-the-slow-cashier-card', 'Nonjudgmental Stance Toward the Slow Cashier Card', 'dbt'::resource_kind, 'A nonjudgmental stance card for the checkout lane that is moving slowly, replacing the verdict with a description.', 'Use it to practice describing instead of judging in a moment where the judgment comes fast.', array['Adults', 'Teens']::text[], 'Five minutes in the lane', 'Have the client catch the judgment as it forms: incompetent, lazy, doing this on purpose. Then they replace it with what they can actually see and what they feel: the cashier is scanning each item and asking a question, I am late and my chest is tight. The card asks for both versions so the client can hear the difference. Many find that the description cools the body faster than the judgment did. Do not ask them to feel kindly; ask them to be accurate.', '[{"id": "f0", "type": "textarea", "label": "The judgment that showed up, word for word:"}, {"id": "f1", "type": "textarea", "label": "What I could actually see the cashier doing:"}, {"id": "f2", "type": "textarea", "label": "What was true about me in that moment, body and schedule:"}, {"id": "f3", "type": "textarea", "label": "The description I replaced the judgment with:"}, {"id": "f4", "type": "textarea", "label": "What changed in my body between the two versions:"}]'::jsonb, array['mindfulness', 'core DBT', 'self-talk']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('dear-man-asking-for-help-carrying-groceries-upstairs-card', 'DEAR MAN Asking for Help Carrying Groceries Upstairs Card', 'dbt'::resource_kind, 'A DEAR MAN script for a small ask the client never makes: help carrying something heavy up the stairs.', 'Use it to practice the skill on a request where the cost of asking is low and the habit of not asking is strong.', array['Adults', 'Teens']::text[], '15 minutes to write, then one ask', 'Walk through each letter for one real ask this week: describe the bags and the stairs, express that it is hard alone, assert the request plainly, reinforce with what the help makes possible, stay mindful of the goal, appear confident, and negotiate if the answer is partial. The ask is deliberately small so the client can watch their own resistance rather than the other person''s. Record what the person said and what the client''s mind predicted they would say.', '[{"id": "f0", "type": "textarea", "label": "Describe: the situation in plain facts:"}, {"id": "f1", "type": "textarea", "label": "Express and Assert: how I will say what it is like and what I am asking for:"}, {"id": "f2", "type": "textarea", "label": "Reinforce: what the help makes possible for both of us:"}, {"id": "f3", "type": "textarea", "label": "What my mind predicts the person will say:"}, {"id": "f4", "type": "textarea", "label": "What they actually said, and how I handled a partial yes:"}]'::jsonb, array['interpersonal effectiveness', 'core DBT', 'DEAR MAN']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('radical-acceptance-of-the-gray-sky-week-card', 'Radical Acceptance of the Gray Sky Week Card', 'dbt'::resource_kind, 'A radical acceptance card for a stretch of flat gray days that the client keeps fighting with the weather.', 'Use it to practice accepting what cannot be changed so energy goes to what can.', array['Adults', 'Teens']::text[], 'Ten minutes daily for a week', 'The client lists what they say and do against the weather each day: the checking of the forecast, the complaints, the plans canceled as if the sky were an insult. Then they write an acceptance sentence they can say without sarcasm, turn the mind each time the fight restarts, and note one thing they did inside the gray that was theirs to choose. Accepting the sky is not liking it; make that explicit or the client will think they are failing at the skill.', '[{"id": "f0", "type": "textarea", "label": "What I have been doing and saying against the gray this week:"}, {"id": "f1", "type": "textarea", "label": "The sentence of acceptance I can say without sarcasm:"}, {"id": "f2", "type": "textarea", "label": "Each day: how many times I had to turn the mind back to it:"}, {"id": "f3", "type": "textarea", "label": "One thing I chose to do inside the gray each day:"}, {"id": "f4", "type": "textarea", "label": "What accepting the sky freed up:"}]'::jsonb, array['acceptance', 'core DBT', 'distress tolerance']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('participate-fully-in-the-saturday-cleaning-playlist-card', 'Participate Fully in the Saturday Cleaning Playlist Card', 'dbt'::resource_kind, 'A participate card for the Saturday clean, throwing the client into the music and the task instead of watching themselves do it.', 'Use it to practice participating without the running commentary that makes chores feel endless.', array['Adults', 'Teens']::text[], '30 minutes', 'Have the client pick a short playlist and one room, and for its length they move with the music and the task, singing if they sing, with the commentary noticed and let go each time it starts. The card asks what the commentary said, how often it pulled them out, and whether the room looked different from how it feels when they clean while narrating. Teenagers often take to this quickly; adults may need permission to look foolish in their own kitchen.', '[{"id": "f0", "type": "textarea", "label": "The playlist and the room I chose:"}, {"id": "f1", "type": "textarea", "label": "What my commentary said while I worked, and how many times it pulled me out:"}, {"id": "f2", "type": "textarea", "label": "The moment I was most fully in it:"}, {"id": "f3", "type": "textarea", "label": "How this clean felt compared with my usual one:"}, {"id": "f4", "type": "textarea", "label": "Another chore I could do with the same throw-myself-in attitude:"}]'::jsonb, array['mindfulness', 'core DBT', 'routines']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('cold-weekend-indoor-or-outdoor-plans-pact-for-partners', 'Cold Weekend Indoor or Outdoor Plans Pact for Partners', 'couples'::resource_kind, 'A pact for the partner who wants to hike in the cold and the partner who wants the couch, with a weekend rhythm both can live with.', 'Use it to turn a recurring winter standoff into an agreed pattern.', array['Couples']::text[], '30 minutes', 'Each partner writes what a good cold weekend looks like for them and what the other''s version costs them, without editing. Then they look for the shape: alternating Saturdays, one shared outdoor hour with a warm reward, separate mornings and a shared evening. Write the pact for the next four weekends and a review date. Watch for one partner conceding everything to end the conversation; ask what they would put in the pact if they were being greedy.', '[{"id": "f0", "type": "textarea", "label": "Partner A: my ideal cold weekend, and what Partner B''s version costs me:"}, {"id": "f1", "type": "textarea", "label": "Partner B: my ideal cold weekend, and what Partner A''s version costs me:"}, {"id": "f2", "type": "textarea", "label": "The pattern we found that gives each of us something:"}, {"id": "f3", "type": "textarea", "label": "Our plan for the next four weekends:"}, {"id": "f4", "type": "textarea", "label": "The date we review it, and what would make us change it:"}]'::jsonb, array['couples', 'planning', 'winter']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('sick-partner-care-preferences-card-for-partners', 'Sick Partner Care Preferences Card for Partners', 'couples'::resource_kind, 'A card where each partner says how they want to be looked after when ill, so the care given matches the care wanted.', 'Use it to stop the hurt that comes when one partner hovers and the other hides.', array['Couples']::text[], '20 minutes', 'Have each partner answer separately: when sick, do they want company or quiet, check-ins or a closed door, soup or nothing, to be asked or to be left to ask. Then compare. Most couples discover they have been giving the care they would want rather than the care the other wants. The card closes with one adjustment each will make and a line about how to say I need something different today without it landing as rejection.', '[{"id": "f0", "type": "textarea", "label": "Partner A: when I am sick I want (company or quiet, check-ins or a closed door, help or space):"}, {"id": "f1", "type": "textarea", "label": "Partner B: when I am sick I want (company or quiet, check-ins or a closed door, help or space):"}, {"id": "f2", "type": "textarea", "label": "Where we have been giving the care we would want instead of the care the other wants:"}, {"id": "f3", "type": "textarea", "label": "One adjustment each of us will make next time:"}, {"id": "f4", "type": "textarea", "label": "How we will say I need something different today:"}]'::jsonb, array['couples', 'support', 'communication']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('earbuds-in-at-home-signal-pact-for-partners', 'Earbuds In at Home Signal Pact for Partners', 'couples'::resource_kind, 'A pact for what earbuds or headphones at home mean: do not disturb, tap me if it matters, or just background noise.', 'Use it to end the daily misread between a partner who wants quiet and a partner who feels shut out.', array['Couples']::text[], '20 minutes', 'Ask each partner what they assume when the other has earbuds in and how that assumption feels. The gap is usually wide: one hears I am recharging, the other hears I would rather not be here. Agree on a signal system, such as one earbud in means interrupt freely, both in means tap and wait, and a time of day when they come out. The pact also names what the shut-out partner can do with the feeling in the meantime.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I assume when Partner B has earbuds in, and how it feels:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I assume when Partner A has earbuds in, and how it feels:"}, {"id": "f2", "type": "textarea", "label": "What the earbuds actually mean for each of us, in our own words:"}, {"id": "f3", "type": "textarea", "label": "Our signal system, and the time of day they come out:"}, {"id": "f4", "type": "textarea", "label": "What the one who feels shut out will do with that feeling while they wait:"}]'::jsonb, array['couples', 'communication', 'boundaries']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('walking-in-the-door-first-ten-minutes-pact-for-partners', 'Walking in the Door First Ten Minutes Pact for Partners', 'couples'::resource_kind, 'A pact for the first ten minutes after one partner gets home, when a bad greeting sets the whole evening.', 'Use it to design a homecoming that neither partner dreads.', array['Couples']::text[], '25 minutes', 'Each partner describes what the first ten minutes look like now from their side, including what they need in that window: a hug, silence, a status report, help with the kids. Then they build a short agreed sequence, such as a greeting first, logistics after ten minutes, and a word either can use when they need a minute alone. The Gottman literature puts weight on these reunions; the pact makes the moment deliberate without making it stiff.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what the first ten minutes are like now, and what I need in them:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what the first ten minutes are like now, and what I need in them:"}, {"id": "f2", "type": "textarea", "label": "Our agreed sequence for the homecoming:"}, {"id": "f3", "type": "textarea", "label": "The word either of us can use when we need a minute alone first:"}, {"id": "f4", "type": "textarea", "label": "After one week: what worked and what we will adjust:"}]'::jsonb, array['couples', 'Gottman', 'connection']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('five-to-one-positive-ratio-weekend-tally-for-partners', 'Five to One Positive Ratio Weekend Tally for Partners', 'couples'::resource_kind, 'A weekend tally where both partners count their positive and negative exchanges, aiming for many more of the first.', 'Use it to show a couple the actual balance of their everyday exchanges, not the remembered one.', array['Couples']::text[], 'One weekend', 'Each partner carries a card and marks a plus for every warm, appreciative or playful exchange and a minus for every criticism, eye roll or cold reply, counting their own behavior only. Sunday night they compare totals and pick the three easiest pluses to add next week. Make clear that the point is not a score to win but a ratio to notice. Couples who come back with ten pluses and no minuses have usually counted the other person; gently redirect.', '[{"id": "f0", "type": "textarea", "label": "Partner A: my pluses and minuses, counted on myself only:"}, {"id": "f1", "type": "textarea", "label": "Partner B: my pluses and minuses, counted on myself only:"}, {"id": "f2", "type": "textarea", "label": "What surprised each of us about our own tally:"}, {"id": "f3", "type": "textarea", "label": "The three easiest pluses we will each add next week:"}, {"id": "f4", "type": "textarea", "label": "The minus each of us is most willing to drop:"}]'::jsonb, array['couples', 'Gottman', 'self-monitoring']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('clothes-hanger-mobile-of-calm-things-craft', 'Clothes Hanger Mobile of Calm Things Craft', 'kids'::resource_kind, 'A hanging mobile made from a clothes hanger and string, each dangling card a picture of something that makes the child feel calm.', 'Use it to give a child a visible, swaying reminder of their calm things above the bed or desk.', array['Children']::text[], '40 minutes', 'The child draws or cuts out five to seven calm things on cards: a pet, a blanket, a song, a person, a place. The parent ties them to a wire hanger at different lengths and hangs it where the child sleeps or works. Each night the parent and child pick one card to talk about for a minute. Watch for a child who cannot think of five; start with two and leave empty strings to fill later, which is itself the conversation.', '[{"id": "f0", "type": "textarea", "label": "The calm things I put on my cards:"}, {"id": "f1", "type": "textarea", "label": "Where my mobile hangs, and who helped me tie it:"}, {"id": "f2", "type": "textarea", "label": "The card we talked about tonight, and what I said:"}, {"id": "f3", "type": "textarea", "label": "A card I want to add later:"}, {"id": "f4", "type": "textarea", "label": "What my grown-up does when I look at my mobile and still feel wobbly:"}]'::jsonb, array['children', 'craft', 'self-soothing']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('paper-cup-stack-knock-down-the-grumpy-tower-play', 'Paper Cup Stack Knock Down the Grumpy Tower Play', 'kids'::resource_kind, 'A play in which the child builds a tower of paper cups labeled with grumpy feelings and knocks it down with a soft ball.', 'Use it to let a child name what is bothering them and move the big feeling through the body safely.', array['Children']::text[], '20 minutes', 'The child writes or draws one grumpy thing on each cup with the parent''s help, stacks them, and from a taped line throws a rolled sock or soft ball to knock the tower down. Rebuild and repeat three times, and on the last round the child chooses which cups to leave off the tower because they feel smaller now. The parent names feelings without fixing them and keeps the throwing aimed at cups only. End with one quiet rebuild where the cups are turned blank side out.', '[{"id": "f0", "type": "textarea", "label": "The grumpy things I wrote or drew on my cups:"}, {"id": "f1", "type": "textarea", "label": "What it felt like when the tower fell:"}, {"id": "f2", "type": "textarea", "label": "Which cups I left off by the third round, and why:"}, {"id": "f3", "type": "textarea", "label": "What my grown-up said while I threw:"}, {"id": "f4", "type": "textarea", "label": "The quiet thing I did at the end:"}]'::jsonb, array['children', 'play', 'anger']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('pom-pom-push-through-the-lid-slow-hands-play', 'Pom-Pom Push Through the Lid Slow Hands Play', 'kids'::resource_kind, 'A slow-hands play where the child pushes pom-poms one at a time through a hole cut in a container lid, naming a slow breath for each.', 'Use it to settle a wound-up child through a quiet, repetitive fine-motor task.', array['Children']::text[], '10 minutes', 'Cut a pom-pom-sized hole in a yogurt or coffee container lid. The child pushes one pom-pom through per slow breath out, and the parent sits beside them breathing at the same pace without talking much. Ten pom-poms is one round. Afterward the child shakes the container to hear the sound and decides whether they need another round. For a child who speeds up, the parent slows their own breath rather than correcting; most children match it within a few pushes.', '[{"id": "f0", "type": "textarea", "label": "How many pom-poms I pushed through, and how many rounds:"}, {"id": "f1", "type": "textarea", "label": "What I noticed about my breathing by the last one:"}, {"id": "f2", "type": "textarea", "label": "The sound the container makes when I shake it:"}, {"id": "f3", "type": "textarea", "label": "How my body felt before and after:"}, {"id": "f4", "type": "textarea", "label": "When my grown-up and I will keep the container handy:"}]'::jsonb, array['children', 'play', 'regulation']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('popsicle-stick-calm-down-choice-fan-craft', 'Popsicle Stick Calm-Down Choice Fan Craft', 'kids'::resource_kind, 'A fan of popsicle sticks joined at one end, each stick a calm-down choice the child can flip out and pick when upset.', 'Use it to give a child a handful of pre-chosen options to pick from when thinking is hard.', array['Children']::text[], '30 minutes', 'The child decorates six to eight popsicle sticks with one calm-down choice each, drawn or written: hug, water, stomp, blanket, count, sing, ask for help, go outside. The parent fastens them at one end with a brad or tape so they fan out. When the child is upset the parent offers the closed fan and the child opens it and taps a stick; the parent does that thing with them. Practice once while calm so the fan is familiar before it is needed.', '[{"id": "f0", "type": "textarea", "label": "The calm-down choices on my sticks:"}, {"id": "f1", "type": "textarea", "label": "Where my fan lives so I can find it:"}, {"id": "f2", "type": "textarea", "label": "The stick I picked the last time I was upset, and what we did:"}, {"id": "f3", "type": "textarea", "label": "A stick that did not help much, and what I will replace it with:"}, {"id": "f4", "type": "textarea", "label": "What my grown-up does when I pick a stick:"}]'::jsonb, array['children', 'craft', 'coping skills']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('spoon-puppet-family-who-says-sorry-play', 'Spoon Puppet Family Who Says Sorry Play', 'kids'::resource_kind, 'A wooden-spoon puppet play where family members act out a small wrong and the words that put it right.', 'Use it to rehearse apology and repair with a child in a way that is play, not a lecture.', array['Children']::text[], '25 minutes', 'The child and parent draw faces on wooden spoons for each family member, then act out a small everyday wrong: a grabbed toy, a snapped word, a broken promise. The spoon who did it tries an apology, and the child decides whether it was a real one and what would make it better. Swap roles so the parent''s spoon apologizes to the child''s. Keep the wrongs small and recent; this is rehearsal for repair, and the parent models being apologized to without piling on.', '[{"id": "f0", "type": "textarea", "label": "The spoons we made and who they are:"}, {"id": "f1", "type": "textarea", "label": "The small wrong we acted out:"}, {"id": "f2", "type": "textarea", "label": "What the sorry spoon said, and whether it was a real sorry:"}, {"id": "f3", "type": "textarea", "label": "What made the sorry better the second time:"}, {"id": "f4", "type": "textarea", "label": "A real sorry I want to say or hear this week:"}]'::jsonb, array['children', 'play', 'repair']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('fruit-salad-switch-seats-if-you-have-ever-game', 'Fruit Salad Switch Seats If You Have Ever Game', 'game'::resource_kind, 'A circle game where the player in the middle calls an experience, everyone it is true for swaps seats, and the one left standing calls next.', 'Use it to show a group how much they share before anyone has to say it out loud.', array['Groups', 'Teens', 'Children']::text[], '20 minutes', 'Chairs in a circle, one fewer than players. The caller in the middle says switch seats if you have ever and finishes the sentence: lost a pet, been new at school, cried at a movie. Everyone it is true for must find a new chair; the one left standing calls next. Set two rules: nothing that singles out one person, and anyone may pass by staying seated. Run ten rounds, then debrief on which round moved the most people and what that tells the group.', '[{"id": "f0", "type": "textarea", "label": "Three sentences I called or wanted to call:"}, {"id": "f1", "type": "textarea", "label": "The round that moved the most people, and how I felt seeing that:"}, {"id": "f2", "type": "textarea", "label": "A round I stayed seated for on purpose, and why:"}, {"id": "f3", "type": "textarea", "label": "Someone I did not expect to switch on the same round as me:"}, {"id": "f4", "type": "textarea", "label": "What the game told us about this group:"}]'::jsonb, array['group', 'game', 'connection']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('captains-coming-listen-and-move-game', 'Captain''s Coming Listen and Move Game', 'game'::resource_kind, 'A listening game with called commands and matching moves, played fast, then slowed down to talk about following directions under pressure.', 'Use it to practice attention and quick regulation in a group that is playful about it.', array['Groups', 'Children', 'Teens']::text[], '20 minutes', 'Teach five commands with moves: captain''s coming is a salute and freeze, scrub the deck is kneeling and scrubbing, man overboard is a hand over the eyes looking out, and so on. The leader calls them faster and faster; a wrong move means sitting out one round, not the whole game. After ten minutes stop and ask what the body did when the calls sped up and what helped them keep up. Then play one slow round where everyone gets every move, so the game ends on competence.', '[{"id": "f0", "type": "textarea", "label": "The command I kept getting wrong, and what my body did when the calls sped up:"}, {"id": "f1", "type": "textarea", "label": "What helped me keep up:"}, {"id": "f2", "type": "textarea", "label": "How it felt to sit out a round, and what I did while I waited:"}, {"id": "f3", "type": "textarea", "label": "The slow round: what was different about getting them all right:"}, {"id": "f4", "type": "textarea", "label": "Where in my week the calls come too fast, and one thing from the game I could use there:"}]'::jsonb, array['group', 'game', 'regulation']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('wax-museum-freeze-when-the-guard-looks-game', 'Wax Museum Freeze When the Guard Looks Game', 'game'::resource_kind, 'A freeze game where players pose as statues and may only move when the guard''s back is turned, then debrief on being watched.', 'Use it to play with the feeling of being watched and the relief of not being, in a group that can laugh about it.', array['Groups', 'Teens', 'Children']::text[], '20 minutes', 'One player is the guard and walks the museum; the others are statues who may move only when the guard is not looking. A statue caught moving becomes a guard too. Play until two guards remain, then switch. The debrief asks what it was like to be watched, how the body felt holding still, and whether anyone moved more boldly once there were two guards and less attention on them. Keep the tone light; the lesson about being watched lands better unforced.', '[{"id": "f0", "type": "textarea", "label": "What my body did while I held a pose and the guard was near:"}, {"id": "f1", "type": "textarea", "label": "What I did when the guard''s back was turned:"}, {"id": "f2", "type": "textarea", "label": "How it felt to become a guard and be the one watching:"}, {"id": "f3", "type": "textarea", "label": "Where in my life I hold still like a statue because someone might be looking:"}, {"id": "f4", "type": "textarea", "label": "One thing from the game I want to remember when I feel watched:"}]'::jsonb, array['group', 'game', 'play']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('telephone-pictionary-folded-paper-game', 'Telephone Pictionary Folded Paper Game', 'game'::resource_kind, 'A folded-paper game where a sentence becomes a drawing becomes a sentence, passed around the circle until the original is unrecognizable.', 'Use it to show a group how messages change in transit and to laugh about misunderstanding.', array['Groups', 'Teens', 'Adults']::text[], '25 minutes', 'Each player writes a short sentence at the top of a strip, folds it so only the sentence shows, and passes left; the next player draws it, folds so only the drawing shows, and passes; the next writes a sentence for the drawing, and so on until the strip comes home. Unfold and read the chain aloud. The debrief turns to real life: a message they sent this week that came out different at the other end, and what gets lost between people who mean well.', '[{"id": "f0", "type": "textarea", "label": "My starting sentence, and what it had become by the end:"}, {"id": "f1", "type": "textarea", "label": "The step where my chain went most wrong:"}, {"id": "f2", "type": "textarea", "label": "A message I sent this week that came out different at the other end:"}, {"id": "f3", "type": "textarea", "label": "What tends to get lost between me and the people I talk to:"}, {"id": "f4", "type": "textarea", "label": "One way I could check what someone actually received:"}]'::jsonb, array['group', 'game', 'communication']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('follow-the-leader-mood-walk-line-game', 'Follow the Leader Mood Walk Line Game', 'game'::resource_kind, 'A follow-the-leader line where the leader walks the way a feeling walks and the line copies, then names the feeling.', 'Use it to help a group read emotion in posture and pace and to practice shifting their own.', array['Groups', 'Children', 'Teens']::text[], '20 minutes', 'Players form a line behind a leader who picks a secret feeling and walks it: heavy and slow, bouncy, hunched and quick. The line copies for a lap, then guesses the feeling; the leader goes to the back and the next player leads. After eight leaders, ask which walk felt most like their own this week and what happened in their body when they copied the opposite walk. Finish with a lap where each player walks the feeling they want to leave with.', '[{"id": "f0", "type": "textarea", "label": "The feeling I walked as leader, and whether the line guessed it:"}, {"id": "f1", "type": "textarea", "label": "The walk that felt most like my own this week:"}, {"id": "f2", "type": "textarea", "label": "What happened in my body when I copied the opposite walk:"}, {"id": "f3", "type": "textarea", "label": "The feeling I chose for the final lap:"}, {"id": "f4", "type": "textarea", "label": "A time this week I could change my walk on purpose:"}]'::jsonb, array['group', 'game', 'emotion identification']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('dark-early-evenings-walk-home-steadiness-plan-sheet', 'Dark Early Evenings Walk Home Steadiness Plan Sheet', 'worksheet'::resource_kind, 'A steadiness plan for the walk home that is now in the dark, with route, pace, company and a grounding anchor chosen in advance.', 'Use it to keep a client moving through a season that makes an ordinary walk feel unsafe.', array['Adults', 'Teens']::text[], '20 minutes', 'When the clocks change, a client who has been doing well can find the walk from the bus or the car suddenly hard. Plan it together: the best-lit route, a pace that is brisk but not fleeing, who they can call or text while walking, and one grounding anchor they can use with their hands or feet on the way. Add a plan for a startle on the way home. Keep this on the stabilizing side; the walk is about getting home steady, not about testing the fear.', '[{"id": "f0", "type": "textarea", "label": "My route home now that it is dark, and the best-lit version of it:"}, {"id": "f1", "type": "textarea", "label": "The pace I will keep, and how I will notice if I start to rush:"}, {"id": "f2", "type": "textarea", "label": "Who I can call or text while I walk:"}, {"id": "f3", "type": "textarea", "label": "My grounding anchor for the way home (hands, feet, breath or sound):"}, {"id": "f4", "type": "textarea", "label": "What I will do if something startles me on the way:"}, {"id": "f5", "type": "textarea", "label": "What I do in the first two minutes after I get inside:"}]'::jsonb, array['PTSD and trauma', 'safety', 'grounding']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('fun-now-means-i-am-disrespecting-what-happened-check-sheet', 'Fun Now Means I Am Disrespecting What Happened Check Sheet', 'cbt'::resource_kind, 'A gentle check on the thought that laughing or having fun now is a betrayal of what the client went through or who they lost.', 'Use it to loosen the guilt that follows a good evening.', array['Adults', 'Teens']::text[], '20 minutes', 'After a client reports a good time and then a wave of guilt, write the thought exactly as it came. Then look together at what enjoyment did and did not change about what happened, what the client would say to a fellow survivor who laughed at a party, and what the guilt might be protecting. Do not argue the client out of the feeling; let the evidence sit beside it. Keep the focus on now, not on the event itself, and do it in session.', '[{"id": "f0", "type": "textarea", "label": "The good moment, and the thought that followed it:"}, {"id": "f1", "type": "textarea", "label": "What my enjoyment changed about what happened, and what it did not:"}, {"id": "f2", "type": "textarea", "label": "What I would say to someone else who went through something hard and laughed at a party:"}, {"id": "f3", "type": "textarea", "label": "What the guilt might be trying to protect or keep:"}, {"id": "f4", "type": "textarea", "label": "A sentence that lets the good moment and the hard history both be true:"}]'::jsonb, array['PTSD and trauma', 'thinking traps', 'self-compassion']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('trauma-memory-as-a-heavy-book-i-can-close-page', 'Trauma Memory as a Heavy Book I Can Close Page', 'act'::resource_kind, 'A defusion page that frames the memory as a heavy book the client can set down and close, without pretending it is not on the shelf.', 'Use it to give a client a way to end contact with a memory on purpose rather than by being flooded.', array['Adults', 'Teens']::text[], '15 minutes', 'The book is on the shelf and always will be; the practice is in choosing when it is open. Have the client describe the cover, the weight, where the shelf is, and what closing it is like, without opening it in session. Then they practice the gesture: noticing the book has opened, naming it, and closing it with a grounding move they choose. This is a stabilizing exercise, not processing; do not ask for the contents, and stop if the client starts reading.', '[{"id": "f0", "type": "textarea", "label": "What my book looks like from the outside: cover, weight, where the shelf is:"}, {"id": "f1", "type": "textarea", "label": "How I know the book has opened on its own:"}, {"id": "f2", "type": "textarea", "label": "The closing gesture I will use, and the grounding move that goes with it:"}, {"id": "f3", "type": "textarea", "label": "What is on the shelf beside the book, in my life now:"}, {"id": "f4", "type": "textarea", "label": "What choosing when it opens would give me:"}]'::jsonb, array['PTSD and trauma', 'defusion', 'pacing']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('half-smile-toward-the-morning-after-a-bad-night-card', 'Half Smile Toward the Morning After a Bad Night Card', 'dbt'::resource_kind, 'A half smile and willing hands card for the first minutes of a day that follows nightmares or no sleep.', 'Use it to give a client a small body-first start to a morning that begins already behind.', array['Adults', 'Teens']::text[], 'Three minutes on waking', 'Teach the half smile and willing hands while the client is calm: the slight upturn of the mouth, the open palms, the shoulders down. Then assign it for the first three minutes after a bad night, before the phone and before the replay. The card asks what the body did and what the mind said about doing something so small. Expect skepticism; the skill is not meant to fix the night, only to stop the morning from being its continuation.', '[{"id": "f0", "type": "textarea", "label": "What my mornings after a bad night usually look like:"}, {"id": "f1", "type": "textarea", "label": "What my face and hands did for the three minutes:"}, {"id": "f2", "type": "textarea", "label": "What my mind said about doing something this small:"}, {"id": "f3", "type": "textarea", "label": "What was different, if anything, about the next ten minutes:"}, {"id": "f4", "type": "textarea", "label": "One more place in the morning I could use this:"}]'::jsonb, array['PTSD and trauma', 'distress tolerance', 'core DBT']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('nightlight-decorating-safe-glow-craft', 'Nightlight Decorating Safe Glow Craft', 'kids'::resource_kind, 'A craft in which the child decorates a plug-in nightlight shade or a jar with a battery light so the dark has a glow they chose.', 'Use it to give a frightened child a say in how the dark looks and a safe object to find at night.', array['Children']::text[], '30 minutes', 'The child decorates a paper or plastic shade for a plug-in nightlight, or a clean jar with a battery tea light inside, using stickers and markers to make a glow that is theirs. The parent helps place it where the child can see it from bed and agrees to the rule that it stays on. Talk together about what the glow means: a reminder that a grown-up is near and the room is the same room. If a child''s fear of the dark follows something that happened, remember your reporting duties if they disclose.', '[{"id": "f0", "type": "textarea", "label": "How I decorated my light:"}, {"id": "f1", "type": "textarea", "label": "Where it sits so I can see it from bed:"}, {"id": "f2", "type": "textarea", "label": "What my light reminds me of when I wake up in the dark:"}, {"id": "f3", "type": "textarea", "label": "What my grown-up does if I call out at night:"}, {"id": "f4", "type": "textarea", "label": "Something else in my room that helps me feel okay:"}]'::jsonb, array['PTSD and trauma', 'children', 'craft', 'safety']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('guest-arriving-in-an-hour-house-not-perfect-worry-sheet', 'Guest Arriving in an Hour House Not Perfect Worry Sheet', 'worksheet'::resource_kind, 'A sheet for the hour before someone comes over, sorting what has to be done from what the worry says has to be done.', 'Use it to help a client stop the pre-guest frenzy and arrive at the door with something left.', array['Adults']::text[], '10 minutes before the next guest', 'Have the client write what the worry demands in the hour before a guest arrives, then mark each item as what the guest would actually notice, what would matter if noticed, and what is for the client''s own nerves. They choose three tasks and stop. The sheet also asks what state they want to greet the guest in and what the frenzy usually costs that. Review after a real visit and note whether anyone mentioned the things left undone.', '[{"id": "f0", "type": "textarea", "label": "Everything the worry says must be done before they arrive:"}, {"id": "f1", "type": "textarea", "label": "Which of those the guest would actually notice, and which would matter:"}, {"id": "f2", "type": "textarea", "label": "The three tasks I will do, and then stop:"}, {"id": "f3", "type": "textarea", "label": "The state I want to be in when I open the door:"}, {"id": "f4", "type": "textarea", "label": "After the visit: what anyone noticed, and how the greeting went:"}]'::jsonb, array['anxiety', 'worry', 'planning']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('a-meeting-invite-with-no-agenda-means-i-am-in-trouble-sheet', 'A Meeting Invite With No Agenda Means I Am in Trouble Sheet', 'cbt'::resource_kind, 'A probability sheet for the calendar invite with no description that the client reads as a reprimand coming.', 'Use it to separate what a blank invite says from what the client fills it with.', array['Adults']::text[], '15 minutes', 'Write the invite as it appeared and the first interpretation. Then list every other reason a manager sends a short invite, estimate how often each has been true in the client''s own history, and put a number on the worst case. Have the client write what they will do with the hours between now and the meeting, since the real cost is usually the waiting. After the meeting, record what it was and re-rate the belief.', '[{"id": "f0", "type": "textarea", "label": "The invite exactly as it appeared, and my first thought:"}, {"id": "f1", "type": "textarea", "label": "Every other reason someone sends a short invite, with how often each has been true for me:"}, {"id": "f2", "type": "textarea", "label": "My honest number for the worst case (0 to 100):"}, {"id": "f3", "type": "textarea", "label": "What I will do with the hours until the meeting:"}, {"id": "f4", "type": "textarea", "label": "What the meeting turned out to be, and my number now:"}]'::jsonb, array['anxiety', 'predictions', 'work']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('anxious-mind-as-a-kid-asking-are-we-there-yet-page', 'Anxious Mind as a Kid Asking Are We There Yet Page', 'act'::resource_kind, 'A defusion page that casts the anxious mind as a child in the back seat asking are we there yet every two minutes.', 'Use it to help a client respond to repeated worry with patience rather than argument or obedience.', array['Adults', 'Teens']::text[], '15 minutes', 'A parent does not pull over every time the question comes, nor shout the child into silence; they say not yet and keep driving. Have the client list the questions their mind asks on repeat and write a not-yet answer for each, short and kind. Then they practice for a day: when the question comes, the answer comes, and the hands stay on the wheel. The page asks what happened to the frequency of the asking when it stopped getting a full stop.', '[{"id": "f0", "type": "textarea", "label": "The questions my mind asks over and over:"}, {"id": "f1", "type": "textarea", "label": "What I usually do when it asks: pull over, argue, or give in?"}, {"id": "f2", "type": "textarea", "label": "My short, kind not-yet answer for each one:"}, {"id": "f3", "type": "textarea", "label": "What happened to the asking over a day of answering this way:"}, {"id": "f4", "type": "textarea", "label": "Where I am actually driving, in my own words:"}]'::jsonb, array['anxiety', 'defusion', 'metaphor']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('cope-ahead-for-the-landlord-walk-through-card', 'Cope Ahead for the Landlord Walk-Through Card', 'dbt'::resource_kind, 'A cope ahead card for the inspection or move-out walk-through where the client expects to be criticized and charged.', 'Use it to rehearse a feared encounter in detail so the skills are ready when it happens.', array['Adults']::text[], '20 minutes', 'Describe the walk-through in detail: the door, the landlord''s clipboard, the room the client is most worried about. Name the emotions likely to show up and the skills that fit each, such as paced breathing in the hallway and DEAR MAN for disputing a charge. Then rehearse it in imagination with the skills in place, twice, including one version where the landlord is unfair. After the real event, record what matched and what the client did well.', '[{"id": "f0", "type": "textarea", "label": "The walk-through in detail: where, who, the room I worry about most:"}, {"id": "f1", "type": "textarea", "label": "The emotions I expect, and the skill I will use for each:"}, {"id": "f2", "type": "textarea", "label": "What I will say if a charge seems unfair:"}, {"id": "f3", "type": "textarea", "label": "How the rehearsal went, including the version where the landlord was unfair:"}, {"id": "f4", "type": "textarea", "label": "After the real event: what matched, and what I did well:"}]'::jsonb, array['anxiety', 'distress tolerance', 'cope ahead']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('text-me-when-you-land-check-in-rules-pact-for-partners', 'Text Me When You Land Check-In Rules Pact for Partners', 'couples'::resource_kind, 'A pact for travel check-ins between partners, with agreed times and a plan for the silence between them.', 'Use it to let the anxious partner feel held and the traveling partner feel trusted.', array['Couples']::text[], '20 minutes', 'Each partner says what check-ins they want when the other travels and what the current pattern costs them: one feels tracked, the other spends the gap imagining a crash. Agree on fixed check-in points, such as landed, at the hotel and goodnight, and on what the waiting partner will do with the quiet instead of texting again. Add a rule for a missed check-in: how long before a call, and who else to call. Review after one trip.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the check-ins I want when my partner travels, and what the current pattern costs me:"}, {"id": "f1", "type": "textarea", "label": "Partner B: the check-ins I want when my partner travels, and what the current pattern costs me:"}, {"id": "f2", "type": "textarea", "label": "Our fixed check-in points:"}, {"id": "f3", "type": "textarea", "label": "What the one at home will do with the quiet between them:"}, {"id": "f4", "type": "textarea", "label": "Our plan for a missed check-in: how long we wait, and who we call:"}]'::jsonb, array['anxiety', 'couples', 'uncertainty']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('put-on-real-clothes-by-ten-micro-step-sheet', 'Put On Real Clothes by Ten Micro Step Sheet', 'worksheet'::resource_kind, 'A micro step sheet for getting out of sleep clothes by mid-morning, tracked for a week with no other goal attached.', 'Use it to give a client one small daily marker that the day has started.', array['Adults', 'Teens']::text[], 'Five minutes daily for one week', 'Pick one target: real clothes by ten, meaning anything they would answer the door in. The sheet tracks the week with a yes or no and one word for how the day went after. Do not stack a shower, breakfast or a walk on top; the single step is the point and the data is what it does to the hours after. Clients often report that the day felt different on the yes days, which opens the behavioral activation conversation without a lecture.', '[{"id": "f0", "type": "textarea", "label": "The clothes that count as real clothes for me:"}, {"id": "f1", "type": "textarea", "label": "Each day this week: did I do it by ten, yes or no:"}, {"id": "f2", "type": "textarea", "label": "One word for how each day went after:"}, {"id": "f3", "type": "textarea", "label": "What got in the way on the no days:"}, {"id": "f4", "type": "textarea", "label": "What I noticed about the yes days:"}]'::jsonb, array['depression', 'behavioral activation', 'routines']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('my-partner-is-only-staying-out-of-obligation-thought-record', 'My Partner Is Only Staying Out of Obligation Thought Record', 'cbt'::resource_kind, 'A thought record for the low-mood conviction that a partner stays from duty rather than love.', 'Use it to examine the mind-reading that low mood does about the people closest to the client.', array['Adults']::text[], '20 minutes', 'Write the thought and its strength, then the evidence on both sides, including what the partner has actually said and done this month and how the client''s mood colors the reading of it. Ask what they would need to see to believe otherwise, and whether anything could count. The alternative thought should be one the client can half believe, not a greeting card. If the relationship is genuinely in trouble, that is a different conversation; this record is for the mood''s version.', '[{"id": "f0", "type": "textarea", "label": "The thought, and how strongly I believe it (0 to 100):"}, {"id": "f1", "type": "textarea", "label": "Evidence for it, in things I have actually seen or heard:"}, {"id": "f2", "type": "textarea", "label": "Evidence against it from this month:"}, {"id": "f3", "type": "textarea", "label": "How my mood is coloring what I count as evidence:"}, {"id": "f4", "type": "textarea", "label": "A thought I can half believe instead, and my rating now:"}]'::jsonb, array['depression', 'thought record', 'relationship issues']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('low-mood-as-mud-season-before-spring-page', 'Low Mood as Mud Season Before Spring Page', 'act'::resource_kind, 'An acceptance page that frames low mood as mud season: slow going, nothing blooming yet, and still a season that passes.', 'Use it to help a client carry the slowness without reading it as a permanent state.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask what mud season looks like where the client grew up or lives: the thaw, the ruts, the boots by the door. Then map it onto now: what is slow going, what has not come up yet, what they are doing anyway with mud on their boots. The page is not a promise that spring arrives on a date; it is a way to hold the heaviness as weather with a direction. Watch for the client who uses the metaphor to wait passively; ask what gets planted in mud.', '[{"id": "f0", "type": "textarea", "label": "What mud season is like where I know it:"}, {"id": "f1", "type": "textarea", "label": "What is slow going for me right now:"}, {"id": "f2", "type": "textarea", "label": "What I am doing anyway, with mud on my boots:"}, {"id": "f3", "type": "textarea", "label": "What I notice when I call this a season instead of a verdict:"}, {"id": "f4", "type": "textarea", "label": "One thing that gets planted in the mud this week:"}]'::jsonb, array['depression', 'acceptance', 'metaphor']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('build-mastery-by-watering-the-one-surviving-plant-card', 'Build Mastery by Watering the One Surviving Plant Card', 'dbt'::resource_kind, 'A build mastery card around the single houseplant that is still alive, cared for on a schedule for one week.', 'Use it to give a client a small, living task that produces a visible result from their effort.', array['Adults', 'Teens']::text[], 'Five minutes twice a week', 'The task is small on purpose: check the soil, water if dry, turn the pot toward the light, note one thing about the plant. The card asks the client to record what they did and what the plant did, and to rate the sense of mastery each time from zero to ten. The dead plants on the shelf are not the subject; the living one is. If the client has no plant, a cutting in a glass of water works and roots within the week.', '[{"id": "f0", "type": "textarea", "label": "The plant, and where it sits:"}, {"id": "f1", "type": "textarea", "label": "Each time this week: what I did for it, and what I noticed about it:"}, {"id": "f2", "type": "textarea", "label": "My mastery rating each time (0 to 10):"}, {"id": "f3", "type": "textarea", "label": "What my mind said about such a small task, and what I did with that:"}, {"id": "f4", "type": "textarea", "label": "What I will care for next if the plant is still with me in two weeks:"}]'::jsonb, array['depression', 'behavioral activation', 'core DBT']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('pass-the-spark-one-thing-that-still-interests-me-game', 'Pass the Spark One Thing That Still Interests Me Game', 'game'::resource_kind, 'A circle game where players pass a small light and the holder names one thing that still holds a flicker of interest, however small.', 'Use it to help a low-mood group find and share what has not gone dark.', array['Groups', 'Adults', 'Teens']::text[], '25 minutes', 'Pass a battery tea light or a small flashlight around the circle. The holder names one thing that still interests them even a little: a show, a recipe, a question they looked up, a sound. Nobody comments; the next player takes the light. Go around three times, and on the third round each player names something another player said that caught them. Debrief on how it felt to say something small out loud and whether any interest grew by being named.', '[{"id": "f0", "type": "textarea", "label": "The three things I named when I held the light:"}, {"id": "f1", "type": "textarea", "label": "Something another player said that caught my interest:"}, {"id": "f2", "type": "textarea", "label": "How it felt to say something small out loud without anyone commenting:"}, {"id": "f3", "type": "textarea", "label": "An interest that felt bigger after I named it:"}, {"id": "f4", "type": "textarea", "label": "One thing from the circle I will do or look into this week:"}]'::jsonb, array['depression', 'group', 'game']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('bills-on-autopay-versus-manual-sweep-sheet', 'Bills on Autopay Versus Manual Sweep Sheet', 'worksheet'::resource_kind, 'A sorting sheet for every recurring bill, deciding which go on autopay and which need a monthly manual check, with one review date.', 'Use it to take late fees and the dread of the mail pile off a client''s plate with one afternoon''s work.', array['Adults']::text[], '45 minutes once, then monthly', 'List every recurring bill with the client, then sort: fixed amounts and trusted companies go on autopay, variable ones get one monthly fifteen-minute sweep on a date that is already an anchor, such as payday. The sheet includes where the passwords live and a text reminder. Watch for the all-at-once plan that never starts; set up two autopays in session and schedule the rest. The follow-up question is what the client will do with the attention they get back.', '[{"id": "f0", "type": "textarea", "label": "Every recurring bill I can think of, with roughly when each is due:"}, {"id": "f1", "type": "textarea", "label": "The ones going on autopay, and which two I will set up today:"}, {"id": "f2", "type": "textarea", "label": "The ones that need a manual check, and my monthly sweep date:"}, {"id": "f3", "type": "textarea", "label": "Where my logins live, and the reminder I will set:"}, {"id": "f4", "type": "textarea", "label": "What I will do with the worry time this frees up:"}]'::jsonb, array['ADHD', 'planning', 'money']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('if-i-cannot-focus-today-i-never-will-fortune-telling-sheet', 'If I Cannot Focus Today I Never Will Fortune Telling Sheet', 'cbt'::resource_kind, 'A fortune-telling sheet for the bad-focus day that becomes a prediction about every day after it.', 'Use it to separate one scattered afternoon from a forecast of the client''s whole future.', array['Adults', 'Teens']::text[], '15 minutes', 'Write the prediction and the day that prompted it. Then have the client look back over the last two weeks and mark the days by how the focus actually went, which almost always shows variation the prediction erased. Add the things that were different about the bad day: sleep, interest, noise, the task itself. Finish with a prediction that fits the data, and a plan for the next scattered day that does not involve giving up on the week.', '[{"id": "f0", "type": "textarea", "label": "The bad-focus day, and the prediction it produced:"}, {"id": "f1", "type": "textarea", "label": "The last two weeks, day by day: how the focus actually went:"}, {"id": "f2", "type": "textarea", "label": "What was different about the bad day (sleep, interest, noise, the task):"}, {"id": "f3", "type": "textarea", "label": "A prediction that fits the record instead of the mood:"}, {"id": "f4", "type": "textarea", "label": "My plan for the next scattered day:"}]'::jsonb, array['ADHD', 'thinking traps', 'predictions']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('attention-as-a-flashlight-with-a-loose-switch-page', 'Attention as a Flashlight With a Loose Switch Page', 'act'::resource_kind, 'A metaphor page that frames attention as a flashlight whose switch flickers, so the practice is re-aiming rather than fixing the switch.', 'Use it to move a client from blaming the switch to practicing the aim.', array['Adults', 'Teens']::text[], '15 minutes', 'The flashlight works; the switch is loose and the beam jumps. Have the client describe where the beam went during one recent task, without judgment, as a list of places. Then practice the re-aim: noticing the beam has moved, naming where it is, and swinging it back, as many times as it takes. Count the re-aims as the work, not as failures. The page asks what the client has been saying about the switch and what changes if the re-aim is the skill.', '[{"id": "f0", "type": "textarea", "label": "One recent task, and every place my beam went during it:"}, {"id": "f1", "type": "textarea", "label": "What I usually say about myself when the beam jumps:"}, {"id": "f2", "type": "textarea", "label": "What a re-aim feels like when I do it on purpose:"}, {"id": "f3", "type": "textarea", "label": "How many re-aims the task took, counted as work rather than failure:"}, {"id": "f4", "type": "textarea", "label": "Where I will practice aiming tomorrow:"}]'::jsonb, array['ADHD', 'metaphor', 'mindfulness']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('cope-ahead-for-the-three-hour-training-session-card', 'Cope Ahead for the Three-Hour Training Session Card', 'dbt'::resource_kind, 'A cope ahead card for the long mandatory training where sitting still and staying tuned in is the whole challenge.', 'Use it to prepare a client for a long stretch of enforced attention with skills chosen in advance.', array['Adults', 'Teens']::text[], '15 minutes, then the session', 'Describe the room, the chair, the slides and the point where the client usually checks out. Name the feelings that will come, such as restlessness and the shame that follows drifting, and the skills for each: a fidget object, a note-taking frame, a planned stand-up at each break, a one-line self-validation for the drift. Rehearse it in imagination, including the moment they notice they have lost ten minutes and come back without a spiral.', '[{"id": "f0", "type": "textarea", "label": "The session in detail, and the point where I usually check out:"}, {"id": "f1", "type": "textarea", "label": "The feelings I expect, and the skill for each:"}, {"id": "f2", "type": "textarea", "label": "What I will bring and what I will do at each break:"}, {"id": "f3", "type": "textarea", "label": "What I will say to myself when I notice I have drifted:"}, {"id": "f4", "type": "textarea", "label": "After the session: what matched, and what I did well:"}]'::jsonb, array['ADHD', 'distress tolerance', 'cope ahead']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('shopping-list-memory-chain-add-one-item-game', 'Shopping List Memory Chain Add One Item Game', 'game'::resource_kind, 'A circle game where each player repeats the shopping list so far and adds one item, with a debrief on what helped the list stick.', 'Use it to make working memory practice playful and to surface each player''s own tricks for remembering.', array['Groups', 'Children', 'Teens']::text[], '20 minutes', 'The first player says I went to the store and bought and names one item; each player repeats the list and adds one. When a player drops an item the group helps rather than eliminates, and the list restarts after it reaches fifteen. Play three rounds. Debrief on what each player did to hold the list: rhythm, pictures, grouping, pointing at people. Those tricks are the takeaway, and the game ends with each player naming one they will try at school or work.', '[{"id": "f0", "type": "textarea", "label": "The longest list our group got to:"}, {"id": "f1", "type": "textarea", "label": "The trick I used to hold the items (rhythm, pictures, grouping, pointing):"}, {"id": "f2", "type": "textarea", "label": "A trick someone else used that I want to borrow:"}, {"id": "f3", "type": "textarea", "label": "What happened in my body when it was my turn and the list was long:"}, {"id": "f4", "type": "textarea", "label": "Where I will try the trick this week:"}]'::jsonb, array['ADHD', 'group', 'game']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('work-trip-hotel-minibar-and-empty-evening-plan-sheet', 'Work Trip Hotel Minibar and Empty Evening Plan Sheet', 'worksheet'::resource_kind, 'A plan for the work trip evening in a hotel room with a minibar, a bar downstairs and nobody who knows the client.', 'Use it to map the hours of a trip where substance use has happened before and fill them on purpose.', array['Adults']::text[], '20 minutes before the trip', 'Have the client walk through the trip hour by hour from checkout at the office to lights out in the hotel, marking where urges have come before: the airport bar, the minibar key, the colleague who suggests one drink. For each, a specific plan: ask the desk to empty the minibar, book the gym or a walk, a call home at a set time, a meeting or a check-in text. The sheet closes with the person they will tell about the plan before they leave.', '[{"id": "f0", "type": "textarea", "label": "The trip hour by hour, from leaving the office to lights out:"}, {"id": "f1", "type": "textarea", "label": "The points where urges have shown up on trips before:"}, {"id": "f2", "type": "textarea", "label": "My plan for each of those points:"}, {"id": "f3", "type": "textarea", "label": "What I will do with the empty evening in the room:"}, {"id": "f4", "type": "textarea", "label": "Who I will tell about this plan before I go, and when I will check in:"}]'::jsonb, array['addiction', 'urges', 'planning']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('stress-this-big-deserves-relief-permission-thought-sheet', 'Stress This Big Deserves Relief Permission Thought Sheet', 'cbt'::resource_kind, 'A sheet for the permission-giving thought that a hard enough day earns a return to substance use.', 'Use it to catch the bargain the mind strikes between stress and relief and offer it other terms.', array['Adults', 'Teens']::text[], '15 minutes', 'Write the thought in the client''s words and the day that produced it. Then look at the bargain: what the relief would actually last, what it would cost by morning, and what the stress would look like tomorrow with the use added on top. Ask what else counts as relief that the mind is not offering, and why. Finish with a response to the thought that honors how hard the day was without accepting the deal. Keep the language to substance use and urges.', '[{"id": "f0", "type": "textarea", "label": "The thought, in my words, and the day that produced it:"}, {"id": "f1", "type": "textarea", "label": "How long the relief would really last, and what the morning would look like:"}, {"id": "f2", "type": "textarea", "label": "What the stress would be tomorrow with the use added:"}, {"id": "f3", "type": "textarea", "label": "Other kinds of relief my mind is not offering, and why it skips them:"}, {"id": "f4", "type": "textarea", "label": "A response to the thought that honors the hard day and declines the deal:"}]'::jsonb, array['addiction', 'thinking traps', 'urges']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('urge-as-a-toddler-tugging-my-sleeve-in-the-store-page', 'Urge as a Toddler Tugging My Sleeve in the Store Page', 'act'::resource_kind, 'A defusion page that casts the urge as a toddler tugging the sleeve for candy at the checkout, persistent and not in charge.', 'Use it to help a client stay kind and firm with an urge instead of fighting it or giving in.', array['Adults', 'Teens']::text[], '15 minutes', 'A toddler tugging at the checkout is loud, sincere and not the one with the wallet. Have the client describe how their urge tugs: the words, the volume, the escalation when ignored. Then write the firm, kind response a steady parent gives, and practice saying it when the tug comes while continuing to do what they came to the store to do. The page asks what happens to the tugging over a few minutes when it gets a no without a fight.', '[{"id": "f0", "type": "textarea", "label": "How my urge tugs: what it says, how loud, what it does when ignored:"}, {"id": "f1", "type": "textarea", "label": "What I usually do when it tugs: give in, argue, or shout at it?"}, {"id": "f2", "type": "textarea", "label": "The firm, kind response I will give it:"}, {"id": "f3", "type": "textarea", "label": "What happened to the tugging over a few minutes of that response:"}, {"id": "f4", "type": "textarea", "label": "What I came into the store for, in my words, and whether I got it:"}]'::jsonb, array['addiction', 'defusion', 'urges']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('pros-and-cons-of-keeping-one-bottle-for-guests-grid', 'Pros and Cons of Keeping One Bottle for Guests Grid', 'dbt'::resource_kind, 'A pros and cons grid for the one bottle kept in the house for guests, weighed in a calm hour rather than during an urge.', 'Use it to make a clear decision about a common early-recovery compromise before it is tested.', array['Adults']::text[], '20 minutes', 'Fill the four boxes with the client: pros and cons of keeping the bottle, pros and cons of not keeping it, with the long-term column weighted. The hospitality argument usually fills one box; ask what the guests would actually think and whether any guest has ever asked. Then the client decides and writes the sentence they will use if someone asks why there is nothing in the house. Revisit the grid if the decision changes; the point is that it was decided, not drifted into.', '[{"id": "f0", "type": "textarea", "label": "Pros of keeping the bottle, short term and long term:"}, {"id": "f1", "type": "textarea", "label": "Cons of keeping it, short term and long term:"}, {"id": "f2", "type": "textarea", "label": "Pros and cons of a house with nothing in it:"}, {"id": "f3", "type": "textarea", "label": "My decision, and the sentence I will use if a guest asks:"}, {"id": "f4", "type": "textarea", "label": "When I will look at this grid again:"}]'::jsonb, array['addiction', 'core DBT', 'decisions']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('recovery-meeting-nights-household-cover-plan-for-partners', 'Recovery Meeting Nights Household Cover Plan for Partners', 'couples'::resource_kind, 'A plan for the evenings one partner is at a recovery meeting, so the other partner''s load is named and the meetings do not become a fight.', 'Use it to protect meeting attendance by making its cost at home visible and shared.', array['Couples']::text[], '25 minutes', 'Each partner writes what meeting nights are like from their side: the one going may feel guilty for leaving, the one staying may feel like a solo parent or a spectator. Then list what has to happen on those nights at home and agree who does it, what the meeting-going partner takes on another night in return, and how the evening ends when they get back. Keep the meetings themselves off the table; the plan is about the household, not whether to go.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what meeting nights are like for me, and what I need on them:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what meeting nights are like for me, and what I need on them:"}, {"id": "f2", "type": "textarea", "label": "What has to happen at home on those nights, and who does it:"}, {"id": "f3", "type": "textarea", "label": "What the partner who goes takes on another night in return:"}, {"id": "f4", "type": "textarea", "label": "How we want the evening to end when they get home:"}]'::jsonb, array['addiction', 'couples', 'support']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('loud-chewing-and-small-noises-irritation-log-sheet', 'Loud Chewing and Small Noises Irritation Log Sheet', 'worksheet'::resource_kind, 'A log for the small sounds that provoke a disproportionate flare, tracked for a week with the state the client was in at the time.', 'Use it to show a client the conditions under which small noises become unbearable.', array['Adults', 'Teens']::text[], 'One week', 'The client logs each flare at a small sound: the sound, who made it, the anger from zero to ten, and what state they were in beforehand, such as tired, hungry, already irritated or trying to concentrate. After a week the pattern is usually about the state, not the sound. The sheet ends with one thing the client will change about the state and one thing they will do in the moment of the sound, which should not be glaring at the person.', '[{"id": "f0", "type": "textarea", "label": "Each flare this week: the sound, who made it, and my anger (0 to 10):"}, {"id": "f1", "type": "textarea", "label": "What state I was in just before each one:"}, {"id": "f2", "type": "textarea", "label": "The pattern I see after a week:"}, {"id": "f3", "type": "textarea", "label": "One thing I will change about the state I am in:"}, {"id": "f4", "type": "textarea", "label": "What I will do in the moment of the sound instead of what I do now:"}]'::jsonb, array['anger management', 'self-monitoring', 'regulation']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('they-should-just-know-better-should-statement-sheet', 'They Should Just Know Better Should Statement Sheet', 'cbt'::resource_kind, 'A should-statement sheet for the anger that comes from expecting other people to know a rule the client never said aloud.', 'Use it to turn an unspoken rule into a request or a letting go.', array['Adults', 'Teens']::text[], '15 minutes', 'Write the should as it sounded in the client''s head and the person it was aimed at. Then ask whether the rule was ever said out loud, where the client learned it, and whether the other person grew up with the same one. Convert the should into a preference, and from there into either a request the client is willing to make or a rule they are willing to drop. The anger often shrinks the moment the rule becomes negotiable.', '[{"id": "f0", "type": "textarea", "label": "The should, exactly as it sounded, and who it was aimed at:"}, {"id": "f1", "type": "textarea", "label": "Whether I have ever said this rule out loud to them:"}, {"id": "f2", "type": "textarea", "label": "Where I learned the rule, and whether they learned the same one:"}, {"id": "f3", "type": "textarea", "label": "The should rewritten as a preference:"}, {"id": "f4", "type": "textarea", "label": "My choice: the request I will make, or the rule I will drop:"}]'::jsonb, array['anger management', 'thinking traps', 'communication']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('anger-as-a-pressure-washer-pointed-at-everything-page', 'Anger as a Pressure Washer Pointed at Everything Page', 'act'::resource_kind, 'A metaphor page that frames anger as a pressure washer: useful on the right surface, destructive when aimed at whatever is nearest.', 'Use it to help a client see anger as a tool to aim rather than a force to suppress or unleash.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask the client what their anger has been pointed at this week and what it did to each surface: the partner, the driver, the self. Then ask what the pressure is actually about and which surface it belongs to, which is often a boundary that was crossed or a value that was stepped on. The practice is noticing the wand swinging toward the nearest person and turning it off until the right surface is in front of them. Not all pressure needs a surface; some just needs the hose off.', '[{"id": "f0", "type": "textarea", "label": "What my anger was pointed at this week, and what it did to each thing:"}, {"id": "f1", "type": "textarea", "label": "What the pressure is actually about underneath:"}, {"id": "f2", "type": "textarea", "label": "The surface it belongs to, if there is one:"}, {"id": "f3", "type": "textarea", "label": "How I will notice the wand swinging toward whoever is nearest:"}, {"id": "f4", "type": "textarea", "label": "What turning it off for a minute would look like for me:"}]'::jsonb, array['anger management', 'metaphor', 'values']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('check-the-facts-on-the-ignored-third-call-to-dinner-card', 'Check the Facts on the Ignored Third Call to Dinner Card', 'dbt'::resource_kind, 'A check the facts card for the parent whose anger spikes when a third call to dinner goes unanswered.', 'Use it to help a parent separate the fact of the unanswered call from the story about disrespect.', array['Adults']::text[], 'Ten minutes', 'Walk through the facts: how many calls, from where, what the children were doing, whether they heard. Then the interpretation: they are ignoring me, they do not respect me, nothing I do matters. Check each against the facts and against what the parent knows about children absorbed in something. Ask whether the anger fits the facts and, if it partly does, what the effective action is, which is rarely the fourth, louder call. Rehearse the walk to the room and the hand on the shoulder.', '[{"id": "f0", "type": "textarea", "label": "The facts: how many calls, from where, what they were doing:"}, {"id": "f1", "type": "textarea", "label": "The story I told myself about why they did not come:"}, {"id": "f2", "type": "textarea", "label": "Which parts of the story the facts support, and which they do not:"}, {"id": "f3", "type": "textarea", "label": "Whether my anger fits the facts, and how big it should be if it does:"}, {"id": "f4", "type": "textarea", "label": "What I will do instead of the fourth call:"}]'::jsonb, array['anger management', 'parenting', 'core DBT']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('red-card-yellow-card-soccer-referee-anger-game', 'Red Card Yellow Card Soccer Referee Anger Game', 'game'::resource_kind, 'A game where players act out heated scenes and a referee flags yellow for a warning sign and red for a line crossed.', 'Use it to teach a group to spot the warning signs of anger and the point where it goes too far.', array['Groups', 'Teens', 'Children']::text[], '30 minutes', 'Two players act a short scene from a card, such as a sibling borrowing something without asking, while a referee with a yellow and a red card watches. Yellow goes up for an early sign of anger, red for a move that crosses a line: a shove, a threat, a slammed door. The actors freeze on red and the group says what could have happened at yellow instead. Rotate roles so everyone referees. The debrief asks each player what their own yellow looks like.', '[{"id": "f0", "type": "textarea", "label": "The scene we acted, and where the referee flagged yellow:"}, {"id": "f1", "type": "textarea", "label": "What happened at red, and what could have happened at yellow instead:"}, {"id": "f2", "type": "textarea", "label": "What my own yellow looks like from the outside:"}, {"id": "f3", "type": "textarea", "label": "A call the referee made that I disagreed with, and why:"}, {"id": "f4", "type": "textarea", "label": "One thing I will do at yellow this week:"}]'::jsonb, array['anger management', 'group', 'game']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('did-i-say-something-wrong-reassurance-asking-log-sheet', 'Did I Say Something Wrong Reassurance Asking Log Sheet', 'worksheet'::resource_kind, 'A log for the repeated question did I say something wrong, tracked with the doubt it was meant to settle and how long the settling lasted.', 'Use it to show a client how briefly reassurance works and what the asking costs the relationship.', array['Adults', 'Teens']::text[], 'One week', 'The client records each time they ask, what the doubt was, the relief from zero to ten, and how long before the doubt returned. Add a column for what the partner did and how the client read it. After a week the data usually shows minutes of relief and hours of doubt. Then set a delay target for the coming week, such as thirty minutes before asking, and name one thing to do with the doubt in that window. Involve the partner only if the client agrees.', '[{"id": "f0", "type": "textarea", "label": "Each time I asked this week: the doubt, the relief (0 to 10), and how long it lasted:"}, {"id": "f1", "type": "textarea", "label": "What my partner did when I asked, and how I read it:"}, {"id": "f2", "type": "textarea", "label": "What the week''s log shows me about reassurance:"}, {"id": "f3", "type": "textarea", "label": "My delay target for next week, and what I will do in the window:"}, {"id": "f4", "type": "textarea", "label": "What I would want my partner to know about this:"}]'::jsonb, array['OCD', 'reassurance seeking', 'self-monitoring']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('a-bad-thought-means-i-secretly-want-it-check-sheet', 'A Bad Thought Means I Secretly Want It Check Sheet', 'cbt'::resource_kind, 'A check sheet for the belief that an intrusive thought about harm or betrayal reveals a hidden wish.', 'Use it to separate the arrival of a thought from its meaning and from the client''s character.', array['Adults', 'Teens']::text[], '20 minutes', 'Write the belief and the kind of thought that triggers it, without the detailed content. Then examine the logic: how the client reacts to the thought, what a person who wanted the thing would feel instead, and what the distress itself suggests about their values. Ask about other unwanted thoughts everybody has and what they say about anybody. The alternative is not I would never think that; it is thoughts arrive, and this one tells me what I care about, not what I want.', '[{"id": "f0", "type": "textarea", "label": "The belief, and the kind of thought that sets it off (no details needed):"}, {"id": "f1", "type": "textarea", "label": "How I react when the thought comes, and what that reaction says about me:"}, {"id": "f2", "type": "textarea", "label": "What someone who actually wanted this would feel instead:"}, {"id": "f3", "type": "textarea", "label": "Other unwanted thoughts most people get, and what they say about anyone:"}, {"id": "f4", "type": "textarea", "label": "A sentence about what the thought tells me and does not tell me:"}]'::jsonb, array['OCD', 'thinking traps', 'intrusive thoughts']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('doubt-as-a-cat-scratching-at-the-door-i-do-not-open-page', 'Doubt as a Cat Scratching at the Door I Do Not Open Page', 'act'::resource_kind, 'A defusion page that frames doubt as a cat scratching at the door: insistent, patient, and quieter once it learns the door stays shut.', 'Use it to help a client let the urge to check or ask go unanswered without fighting it.', array['Adults', 'Teens']::text[], '15 minutes', 'The cat scratches; the client has learned that opening the door brings it in for a while and then it scratches again. Have them describe their cat: what it scratches for, how it escalates, how long it keeps on when the door stays shut. The practice is hearing the scratching, naming it, and staying in the chair. The page asks what the scratching did over a week of unopened doors. Do not promise silence; promise a cat that learns.', '[{"id": "f0", "type": "textarea", "label": "What my doubt scratches for, and how it escalates when ignored:"}, {"id": "f1", "type": "textarea", "label": "What happens when I open the door: how long until it scratches again?"}, {"id": "f2", "type": "textarea", "label": "What I will do in the chair while it scratches:"}, {"id": "f3", "type": "textarea", "label": "What the scratching did over a week of unopened doors:"}, {"id": "f4", "type": "textarea", "label": "What I got done in the room while the door stayed shut:"}]'::jsonb, array['OCD', 'defusion', 'uncertainty']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('turning-the-mind-from-the-rinsed-enough-dish-card', 'Turning the Mind From the Rinsed-Enough Dish Card', 'dbt'::resource_kind, 'A turning the mind card for the dish that feels not quite clean, choosing to put it in the rack and turning back each time the urge returns.', 'Use it to practice the repeated choice of acceptance in a small daily moment.', array['Adults', 'Teens']::text[], 'Five minutes at the sink', 'Teach turning the mind as a fork in the road: the dish is rinsed enough, and each time the mind says once more the client notices the fork and chooses the rack again. The card counts the turns. The point is not to win the argument about cleanliness but to practice the choosing. Pair it with a willing-hands posture at the sink and a word for the choice. Clients who find the dish too hard can start with a mug.', '[{"id": "f0", "type": "textarea", "label": "The dish, and how many times my mind said once more:"}, {"id": "f1", "type": "textarea", "label": "How many times I turned back to the choice of the rack:"}, {"id": "f2", "type": "textarea", "label": "What the urge did while I dried my hands and walked away:"}, {"id": "f3", "type": "textarea", "label": "The word or gesture I used for the choice:"}, {"id": "f4", "type": "textarea", "label": "What I will practice turning the mind on next:"}]'::jsonb, array['OCD', 'acceptance', 'core DBT']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('messy-finger-paint-hands-wait-one-minute-play', 'Messy Finger Paint Hands Wait One Minute Play', 'kids'::resource_kind, 'A play in which the child finger paints and keeps the messy hands up for one minute before washing, with the parent cheering.', 'Use it to help a child who cannot bear mess practice staying in it a little longer, with a grown-up beside them.', array['Children']::text[], '20 minutes', 'Set up finger paints on a covered table. The child paints a picture, and when they are done the parent starts a one-minute timer while the child holds up the painted hands and names what they feel: sticky, yucky, wiggly. The parent counts down and cheers at the end; then the child washes. Repeat another day with two minutes if the child agrees. The parent does not wipe for them or rush the timer, and names the brave part out loud.', '[{"id": "f0", "type": "textarea", "label": "What I painted:"}, {"id": "f1", "type": "textarea", "label": "What my hands felt like while the timer ran:"}, {"id": "f2", "type": "textarea", "label": "The uh-oh feeling at the start, and how big it was by the end (0 to 10):"}, {"id": "f3", "type": "textarea", "label": "What my grown-up said while we waited:"}, {"id": "f4", "type": "textarea", "label": "Whether I want to try two minutes next time:"}]'::jsonb, array['OCD', 'children', 'play', 'exposure']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('grocery-store-checkout-line-surge-plan-sheet', 'Grocery Store Checkout Line Surge Plan Sheet', 'worksheet'::resource_kind, 'A plan for a surge of panic in the checkout line with a full cart, where leaving feels impossible and staying feels worse.', 'Use it to give a client a rehearsed sequence for the most trapped-feeling minute of the shopping trip.', array['Adults', 'Teens']::text[], '15 minutes, then the next trip', 'Map the line: where the surge usually starts, what the body does first, and what the client has done before, such as abandoning the cart. Then write the plan in order: the first body sign, the grounding move with the hands on the cart handle, the sentence they say to themselves, and what they do if the surge peaks, including the option of stepping aside and coming back. The plan is about riding it out in place when possible, not escaping faster. Review after one real trip.', '[{"id": "f0", "type": "textarea", "label": "Where in the line the surge usually starts, and the first sign in my body:"}, {"id": "f1", "type": "textarea", "label": "What I have done before when it hit:"}, {"id": "f2", "type": "textarea", "label": "My grounding move with my hands on the cart:"}, {"id": "f3", "type": "textarea", "label": "The sentence I say to myself while I wait:"}, {"id": "f4", "type": "textarea", "label": "What I will do if it peaks, and how I will come back if I step aside:"}, {"id": "f5", "type": "textarea", "label": "After the next trip: what happened, and how long the peak lasted:"}]'::jsonb, array['panic attacks', 'planning', 'grounding']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('numb-lips-mean-something-is-very-wrong-fact-check-sheet', 'Numb Lips Mean Something Is Very Wrong Fact Check Sheet', 'cbt'::resource_kind, 'A fact check sheet for the tingling or numbness around the mouth during panic and the medical catastrophe the client attaches to it.', 'Use it to connect a frightening sensation to its ordinary cause in fast breathing.', array['Adults', 'Teens']::text[], '15 minutes', 'Write the sensation and the feared meaning. Then review what the client knows about rapid breathing and the tingling it produces, how many times this sensation has come and gone with panic, and what a medical emergency would look like alongside it. If the client has not had a medical visit for recurring symptoms, encourage one; the sheet is for sensations their doctor has already heard about. Finish with a sentence to say the next time the lips tingle.', '[{"id": "f0", "type": "textarea", "label": "The sensation, and what I fear it means:"}, {"id": "f1", "type": "textarea", "label": "What I know about fast breathing and tingling:"}, {"id": "f2", "type": "textarea", "label": "How many times this has come and gone, and what happened each time:"}, {"id": "f3", "type": "textarea", "label": "What an actual emergency would look like next to it:"}, {"id": "f4", "type": "textarea", "label": "The sentence I will say next time my lips go numb:"}]'::jsonb, array['panic attacks', 'thinking traps', 'sensations']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('panic-as-a-roller-coaster-i-did-not-line-up-for-page', 'Panic as a Roller Coaster I Did Not Line Up For Page', 'act'::resource_kind, 'An acceptance page that frames a panic surge as a roller coaster the client is already strapped into: timed, and over when it is over.', 'Use it to help a client ride the surge rather than grab for the exit mid-ride.', array['Adults', 'Teens']::text[], '15 minutes', 'Nobody gets off a roller coaster at the top of the hill; the only way down is the track. Have the client describe their coaster: the climb, the drop, the length, where they usually try to unbuckle. Then write what riding it out would look like, hands up or holding the bar, breath where it can go, eyes on something in the car. The page asks how long the ride actually lasts when timed. Clients are often surprised that the drop is shorter than the climb.', '[{"id": "f0", "type": "textarea", "label": "My coaster: what the climb feels like, where the drop is, how long it lasts:"}, {"id": "f1", "type": "textarea", "label": "Where on the ride I usually try to unbuckle:"}, {"id": "f2", "type": "textarea", "label": "What riding it out would look like for me, hands and breath and eyes:"}, {"id": "f3", "type": "textarea", "label": "How long the ride actually lasted the last time I timed it:"}, {"id": "f4", "type": "textarea", "label": "What I did when the car came back to the platform:"}]'::jsonb, array['panic attacks', 'acceptance', 'metaphor']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('half-smile-through-the-rising-heartbeat-card', 'Half Smile Through the Rising Heartbeat Card', 'dbt'::resource_kind, 'A half smile and willing hands card for the first thirty seconds of a rising heartbeat, before the mind decides what it means.', 'Use it to put a body-first skill at the very start of a surge.', array['Adults', 'Teens']::text[], 'One minute when it starts', 'Practice the posture while calm: lips barely turned up, palms open on the thighs, shoulders dropped. Then assign it for the first thirty seconds of any rising heartbeat: posture first, meaning later. The card asks what the heartbeat did when the face and hands did not join the alarm. It will not stop a surge, and say so; it changes what the body tells the mind in the opening seconds, which is often where the climb gets steeper or does not.', '[{"id": "f0", "type": "textarea", "label": "Where I was when the heartbeat started to rise:"}, {"id": "f1", "type": "textarea", "label": "What my face and hands did in the first thirty seconds:"}, {"id": "f2", "type": "textarea", "label": "What my mind wanted to decide about the heartbeat, and whether I let it wait:"}, {"id": "f3", "type": "textarea", "label": "What the heartbeat did over the next minute:"}, {"id": "f4", "type": "textarea", "label": "What I noticed that was different from my usual first thirty seconds:"}]'::jsonb, array['panic attacks', 'distress tolerance', 'core DBT']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('driving-partner-pull-over-signal-plan-for-partners', 'Driving Partner Pull Over Signal Plan for Partners', 'couples'::resource_kind, 'A plan for a panic surge while driving: the signal, who says pull over, where, and what each partner does for the next five minutes.', 'Use it to make a frightening moment in the car predictable for both partners.', array['Couples']::text[], '20 minutes', 'The partner who gets surges describes what happens at the wheel and what they need from the passenger; the passenger describes what they see and what they are afraid of doing wrong. Agree on a signal word, the rule that either partner can call a pull-over, what counts as a safe spot, and a five-minute sequence once stopped: hazards on, breathing together, no questions about causes. Add a rule for who drives afterward and how that is decided without shame.', '[{"id": "f0", "type": "textarea", "label": "Partner A (who gets the surges): what happens at the wheel, and what I need from you:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I see, and what I am afraid of getting wrong:"}, {"id": "f2", "type": "textarea", "label": "Our signal word, and the rule that either of us can call a pull-over:"}, {"id": "f3", "type": "textarea", "label": "The five-minute sequence once we are stopped:"}, {"id": "f4", "type": "textarea", "label": "How we decide who drives afterward, without shame:"}]'::jsonb, array['panic attacks', 'couples', 'safety']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('allowance-and-chores-link-or-separate-decision-sheet', 'Allowance and Chores Link or Separate Decision Sheet', 'worksheet'::resource_kind, 'A decision sheet for whether a child''s allowance is tied to chores, kept separate, or split, with the reasons on each side written out.', 'Use it to help a parent make one clear household rule instead of renegotiating it weekly.', array['Adults']::text[], '25 minutes', 'Have the parent, or both parents, write what they want the allowance to teach and what they want the chores to teach; these are often different lessons, which is the whole question. List the pros of linking them, the pros of keeping them separate, and a possible split such as base chores unpaid and extra jobs paid. Decide, write the rule in words a child could repeat, and set a date to review it. Watch for a rule designed to win an argument that happened last Tuesday.', '[{"id": "f0", "type": "textarea", "label": "What I want the allowance to teach, and what I want the chores to teach:"}, {"id": "f1", "type": "textarea", "label": "Reasons to link them, and reasons to keep them separate:"}, {"id": "f2", "type": "textarea", "label": "A split version worth considering:"}, {"id": "f3", "type": "textarea", "label": "Our rule, in words my child could repeat back:"}, {"id": "f4", "type": "textarea", "label": "When we review it, and what would make us change it:"}]'::jsonb, array['parenting', 'decisions', 'family']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('a-teacher-email-means-my-child-is-in-trouble-thought-record', 'A Teacher Email Means My Child Is in Trouble Thought Record', 'cbt'::resource_kind, 'A thought record for the stomach drop when a teacher''s name appears in the inbox and the parent assumes the worst.', 'Use it to separate the arrival of an email from the catastrophe the parent reads into it.', array['Adults']::text[], '15 minutes', 'Write the thought when the email appeared, before it was opened, and the feeling with it. Then list what teacher emails have actually contained over the school year and how many were trouble. Look at what the parent''s own school history adds to the reaction. Finish with a response for next time, including a rule about opening the email before predicting it. If the email was in fact about a problem, the record still helps separate the problem from the verdict on the parent.', '[{"id": "f0", "type": "textarea", "label": "The thought when I saw the teacher''s name, before I opened it:"}, {"id": "f1", "type": "textarea", "label": "What teacher emails have actually said this year, and how many were about a problem:"}, {"id": "f2", "type": "textarea", "label": "What my own school years add to this reaction:"}, {"id": "f3", "type": "textarea", "label": "What the email turned out to be:"}, {"id": "f4", "type": "textarea", "label": "My rule for the next one:"}]'::jsonb, array['parenting', 'thought record', 'predictions']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('values-when-my-child-is-not-invited-to-the-party-page', 'Values When My Child Is Not Invited to the Party Page', 'act'::resource_kind, 'A values page for the parent whose child was left off an invitation list, holding the parent''s own hurt apart from the child''s.', 'Use it to help a parent act from what they want to teach rather than from their own old sting.', array['Adults']::text[], '15 minutes', 'Ask the parent what came up when they heard, and how much of it was theirs: memories of their own exclusions, anger at other parents, the urge to fix it. Then ask what they want their child to learn from being left out sometimes, and what response would teach that. The page separates what the parent will do with their own feeling from what they will say to the child. Watch for the fix, such as calling the host, being chosen before the value has been named.', '[{"id": "f0", "type": "textarea", "label": "What came up in me when I heard, and how much of it is mine rather than my child''s:"}, {"id": "f1", "type": "textarea", "label": "What I want my child to learn about being left out sometimes:"}, {"id": "f2", "type": "textarea", "label": "What I will say to my child, and what I will not:"}, {"id": "f3", "type": "textarea", "label": "What I will do with my own feeling, away from them:"}, {"id": "f4", "type": "textarea", "label": "The value I want them to see in how I handled it:"}]'::jsonb, array['parenting', 'values', 'self-compassion']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('fast-skill-when-my-teen-asks-for-the-car-again-card', 'FAST Skill When My Teen Asks for the Car Again Card', 'dbt'::resource_kind, 'A FAST card for the parent who keeps saying yes to the car to avoid the argument and resents it afterward.', 'Use it to help a parent hold a no with self-respect instead of caving or lecturing.', array['Adults']::text[], 'Ten minutes before the next ask', 'Walk through FAST for the next request: be fair to the teen and to themselves, no over-apologizing for the no, stick to the values about safety or fairness that the no rests on, and be truthful about the reason rather than inventing an errand. Script the no in two sentences. The card asks what the parent usually says instead and what the resentment costs the relationship. Rehearse the teen''s pushback and the repeat of the same two sentences.', '[{"id": "f0", "type": "textarea", "label": "What I usually say when my teen asks for the car, and what I feel afterward:"}, {"id": "f1", "type": "textarea", "label": "Fair: what is fair to them and to me here:"}, {"id": "f2", "type": "textarea", "label": "The value my no rests on, and the truthful reason I will give:"}, {"id": "f3", "type": "textarea", "label": "My two-sentence no:"}, {"id": "f4", "type": "textarea", "label": "What I will say when they push back the first and second time:"}]'::jsonb, array['parenting', 'interpersonal effectiveness', 'FAST']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('bedtime-train-cars-paper-chain-steps-craft', 'Bedtime Train Cars Paper Chain Steps Craft', 'kids'::resource_kind, 'A craft in which the child makes a paper train, one car per bedtime step, and moves a clothespin engine along it each night.', 'Use it to make the bedtime routine visible and let the child drive it.', array['Children']::text[], '30 minutes to make, then nightly', 'The child and parent cut five or six paper train cars and draw one bedtime step on each: pajamas, teeth, book, hug, lights. Tape them in a line at the child''s height and clip a clothespin engine to the first car. Each night the child moves the engine as the steps are done. The parent''s job is to point at the train instead of giving instructions, and to add no cars without the child''s agreement. Watch for a train with ten cars; fewer steps done every night beats more done sometimes.', '[{"id": "f0", "type": "textarea", "label": "The steps on my train cars, in order:"}, {"id": "f1", "type": "textarea", "label": "Where my train is taped up:"}, {"id": "f2", "type": "textarea", "label": "Who moves the engine, and what my grown-up does instead of telling me:"}, {"id": "f3", "type": "textarea", "label": "The car that is hardest to get past, and one idea for it:"}, {"id": "f4", "type": "textarea", "label": "How bedtime felt the first week with the train:"}]'::jsonb, array['parenting', 'children', 'craft', 'routines']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('pregnancy-appointment-questions-list-and-advocate-sheet', 'Pregnancy Appointment Questions List and Advocate Sheet', 'worksheet'::resource_kind, 'A sheet for the expecting parent to write the questions they keep forgetting to ask and to name who will help them be heard.', 'Use it to help a client leave appointments with answers instead of regrets.', array['Adults']::text[], '15 minutes before each appointment', 'Many expecting parents freeze in the appointment and remember the questions in the parking lot. Have the client write every question before the visit, rank the top three, and decide who comes with them or who they will call afterward. Add a line for what to say if they feel rushed. After the appointment they record what was answered and what was deferred. Keep this on the practical side; the worry itself can be worked elsewhere.', '[{"id": "f0", "type": "textarea", "label": "Every question I have before this appointment:"}, {"id": "f1", "type": "textarea", "label": "My top three, in order:"}, {"id": "f2", "type": "textarea", "label": "Who comes with me or who I call after, and what I want them to do:"}, {"id": "f3", "type": "textarea", "label": "What I will say if I feel rushed:"}, {"id": "f4", "type": "textarea", "label": "After the visit: what was answered, and what I still need to ask:"}]'::jsonb, array['perinatal and postpartum', 'planning', 'assertiveness']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('calling-the-pediatrician-again-makes-me-a-nuisance-record', 'Calling the Pediatrician Again Makes Me a Nuisance Record', 'cbt'::resource_kind, 'A thought record for the new parent who holds back a second call to the doctor''s office for fear of being a bother.', 'Use it to separate reasonable follow-up from the belief that asking makes the client a problem.', array['Adults']::text[], '15 minutes', 'Write the thought and the question the client did not ask. Then look at what the office is for, what the client would tell a friend holding the same question, and what has actually happened the times they did call back. Weigh the cost of asking against the cost of not knowing at 2 a.m. The alternative thought should give the client permission without pretending the shyness is gone. If the question is about the baby''s safety, the record ends with the call being made.', '[{"id": "f0", "type": "textarea", "label": "The thought, and the question I did not ask:"}, {"id": "f1", "type": "textarea", "label": "What the office is there for, and what has happened the times I called back:"}, {"id": "f2", "type": "textarea", "label": "What I would tell a friend holding the same question:"}, {"id": "f3", "type": "textarea", "label": "The cost of asking next to the cost of not knowing tonight:"}, {"id": "f4", "type": "textarea", "label": "A thought I can carry into the next call:"}]'::jsonb, array['perinatal and postpartum', 'thought record', 'self-criticism']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('postpartum-mind-as-a-news-ticker-of-worst-cases-page', 'Postpartum Mind as a News Ticker of Worst Cases Page', 'act'::resource_kind, 'A defusion page that frames the new parent''s mind as a news ticker scrolling worst cases under every ordinary moment.', 'Use it to help a client notice the ticker without reading every headline as a bulletin.', array['Adults']::text[], '15 minutes', 'Have the client write a few headlines their ticker ran today, without detail: the one about the stairs, the one about the breathing. Then practice reading them as a ticker: noticing the scroll, saying there goes the ticker, and returning the eyes to the baby or the dish. The page asks what the ticker does over a day of being noticed rather than watched. Intrusive worst-case thoughts are common after a birth; if a thought comes with an urge to act on it, that is a different conversation to have now.', '[{"id": "f0", "type": "textarea", "label": "A few headlines my ticker ran today, in a word or two each:"}, {"id": "f1", "type": "textarea", "label": "What I usually do when a headline scrolls past:"}, {"id": "f2", "type": "textarea", "label": "What it was like to say there goes the ticker and look back at what I was doing:"}, {"id": "f3", "type": "textarea", "label": "What the ticker did over a day of being noticed instead of watched:"}, {"id": "f4", "type": "textarea", "label": "What I was able to be present for while it scrolled:"}]'::jsonb, array['perinatal and postpartum', 'defusion', 'intrusive thoughts']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('give-skills-with-the-nurse-who-sounded-short-card', 'GIVE Skills With the Nurse Who Sounded Short Card', 'dbt'::resource_kind, 'A GIVE card for the postpartum client who left a call with a nurse feeling scolded and now avoids calling at all.', 'Use it to keep a client in contact with care by giving them a way to handle a brusque exchange.', array['Adults']::text[], 'Ten minutes', 'Replay the call: what the nurse said, what the client heard, and what they did afterward. Then plan the next call with GIVE: a gentle opening, interest in what the nurse is asking, a validation of how busy the line is, and an easy manner that does not apologize for calling. Script the first two sentences. The card also asks what the client will do with the sting if the next call is short too; the care is worth more than the tone.', '[{"id": "f0", "type": "textarea", "label": "What the nurse said, what I heard, and what I did afterward:"}, {"id": "f1", "type": "textarea", "label": "Gentle and Interested: how I will open the next call:"}, {"id": "f2", "type": "textarea", "label": "Validate: one line about how busy they are:"}, {"id": "f3", "type": "textarea", "label": "Easy manner: what I will not apologize for:"}, {"id": "f4", "type": "textarea", "label": "What I will do with the sting if the next call is short too:"}]'::jsonb, array['perinatal and postpartum', 'interpersonal effectiveness', 'GIVE']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('grandparent-childcare-offers-pact-for-new-parents', 'Grandparent Childcare Offers Pact for New Parents', 'couples'::resource_kind, 'A pact for new parents on which grandparent childcare offers they accept, which they decline, and how they say so as one voice.', 'Use it to stop a generous offer from becoming an argument between partners.', array['Couples']::text[], '25 minutes', 'Each partner writes what help they want from each set of grandparents and what makes them uneasy, such as rules not followed or visits that do not end. Compare without defending anyone''s parents. Then agree on which offers get a yes, which get a not yet, and the exact sentence for a decline, said by the partner whose parents they are. Add what happens when a grandparent goes around one partner to the other. Review after the first month.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the help I want from each set of grandparents, and what makes me uneasy:"}, {"id": "f1", "type": "textarea", "label": "Partner B: the help I want from each set of grandparents, and what makes me uneasy:"}, {"id": "f2", "type": "textarea", "label": "Offers we say yes to, and offers that are a not yet:"}, {"id": "f3", "type": "textarea", "label": "Our sentence for declining, and who says it to whom:"}, {"id": "f4", "type": "textarea", "label": "What we do when a grandparent goes around one of us to the other:"}]'::jsonb, array['perinatal and postpartum', 'couples', 'family']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('introducing-myself-without-apologizing-log-sheet', 'Introducing Myself Without Apologizing Log Sheet', 'worksheet'::resource_kind, 'A log of every introduction the client makes in a week, catching the sorry, the just and the shrinking that creep into the first sentence.', 'Use it to show a client how they present themselves before anyone else has judged them.', array['Adults', 'Teens']::text[], 'One week', 'The client records each introduction, in person or by email: the words they used, the hedges in it such as sorry to bother you or I just, and how they felt afterward. At the end of the week they rewrite three of them without the hedges and say the new versions aloud in session. Watch for the client who hears the rewrite as arrogant; ask whether they would call a colleague arrogant for saying the same words.', '[{"id": "f0", "type": "textarea", "label": "Each introduction this week, and the words I actually used:"}, {"id": "f1", "type": "textarea", "label": "The hedges I spotted in them (sorry, just, only, if that is okay):"}, {"id": "f2", "type": "textarea", "label": "How I felt after each one:"}, {"id": "f3", "type": "textarea", "label": "Three introductions rewritten without the hedges:"}, {"id": "f4", "type": "textarea", "label": "What it was like to say the rewritten versions aloud:"}]'::jsonb, array['self-esteem', 'self-monitoring', 'assertiveness']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('if-i-say-no-they-will-replace-me-thought-record', 'If I Say No They Will Replace Me Thought Record', 'cbt'::resource_kind, 'A thought record for the belief that a single refusal, at work or among friends, will get the client swapped out for someone easier.', 'Use it to examine the conditional-worth rule that makes every no feel like a resignation.', array['Adults', 'Teens']::text[], '20 minutes', 'Write the thought and the request the client wanted to refuse. Gather evidence: times they have said no and what happened, times others said no to them and whether they replaced anyone, and what they are actually valued for. Ask what being irreplaceable only because they never refuse would mean about the relationship. The alternative thought should allow for the possibility that some people would push back, and that the client could survive that.', '[{"id": "f0", "type": "textarea", "label": "The thought, and the request I wanted to refuse:"}, {"id": "f1", "type": "textarea", "label": "Times I have said no before, and what actually happened:"}, {"id": "f2", "type": "textarea", "label": "Times others said no to me, and whether I replaced them:"}, {"id": "f3", "type": "textarea", "label": "What people actually value me for, as best I can tell:"}, {"id": "f4", "type": "textarea", "label": "An alternative thought that leaves room for some pushback:"}]'::jsonb, array['self-esteem', 'thought record', 'boundaries']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('self-worth-as-the-soil-not-the-harvest-page', 'Self-Worth as the Soil Not the Harvest Page', 'act'::resource_kind, 'A metaphor page that places worth in the soil, which is there in every season, rather than in the harvest the client is judged on.', 'Use it to help a client hold their value apart from this year''s results.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask what the client counts as harvest: grades, promotions, praise, a clean house. Then ask what was there in the years the harvest was thin, and what in them made any harvest possible at all: care, effort, curiosity, the people they kept. That is the soil. The page asks them to describe their soil in plain words and to notice what it is like to stand on it rather than wait for the crop. Watch for the client who turns the soil into another thing to grade.', '[{"id": "f0", "type": "textarea", "label": "What I have been counting as the harvest:"}, {"id": "f1", "type": "textarea", "label": "What was still there in a year when the harvest was thin:"}, {"id": "f2", "type": "textarea", "label": "My soil, in plain words: what in me makes any harvest possible:"}, {"id": "f3", "type": "textarea", "label": "What it is like to stand on the soil instead of waiting for the crop:"}, {"id": "f4", "type": "textarea", "label": "One thing I will do this week that tends the soil rather than the yield:"}]'::jsonb, array['self-esteem', 'metaphor', 'values']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('self-validation-after-the-mistake-at-work-card', 'Self-Validation After the Mistake at Work Card', 'dbt'::resource_kind, 'A self-validation card for the hours after a workplace error, when the inner voice is harsher than any manager would be.', 'Use it to give a client a way to acknowledge the mistake and the feeling without piling on.', array['Adults']::text[], 'Ten minutes', 'Teach self-validation as the same skill they would use for a colleague: name the feeling, say why it makes sense, and treat themselves as someone who is still competent. The card walks through a real mistake: the facts, the feeling, the sentence of validation, and the one corrective step that is actually theirs to take. Watch for validation turning into excuse-making or into a second round of blame; it is neither.', '[{"id": "f0", "type": "textarea", "label": "The mistake, in plain facts:"}, {"id": "f1", "type": "textarea", "label": "What I felt, and what the harsh voice said:"}, {"id": "f2", "type": "textarea", "label": "Why the feeling makes sense, in one sentence:"}, {"id": "f3", "type": "textarea", "label": "What I would say to a colleague who made the same mistake:"}, {"id": "f4", "type": "textarea", "label": "The one corrective step that is mine to take, and when I will take it:"}]'::jsonb, array['self-esteem', 'self-compassion', 'core DBT']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('two-compliments-and-a-lie-guess-which-game', 'Two Compliments and a Lie Guess Which Game', 'game'::resource_kind, 'A group game where each player writes two true compliments about themselves and one invented one, and the group guesses the invention.', 'Use it to get a group saying true good things about themselves under the cover of a game.', array['Groups', 'Teens', 'Adults']::text[], '25 minutes', 'Each player writes three statements about themselves in the form of compliments, two true and one made up, and reads them aloud. The group votes on which is the lie, and the player reveals it. Rule: the true ones must be things the player actually believes, not jokes. Go around once, then debrief: which true compliment was hardest to write, whether anyone was surprised by what the group believed, and what it was like to hear the true ones taken seriously.', '[{"id": "f0", "type": "textarea", "label": "My two true compliments and my one invented one:"}, {"id": "f1", "type": "textarea", "label": "Which one the group thought was the lie, and why:"}, {"id": "f2", "type": "textarea", "label": "The true one that was hardest to write down:"}, {"id": "f3", "type": "textarea", "label": "What it was like to hear the group believe the true ones:"}, {"id": "f4", "type": "textarea", "label": "A compliment I wrote that I will try to believe a little more this week:"}]'::jsonb, array['self-esteem', 'group', 'game']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('asking-a-coworker-to-lunch-steps-sheet', 'Asking a Coworker to Lunch Steps Sheet', 'worksheet'::resource_kind, 'A step sheet for asking one coworker to lunch, from choosing the person to the first sentence to what to do with a maybe.', 'Use it to turn a vague wish for workplace friends into one concrete, rehearsed ask.', array['Adults']::text[], '20 minutes, then one ask', 'Have the client pick a coworker they find easy, not the one they most want to impress, and a low-stakes format such as walking to get coffee. Write the exact sentence, the day, and the plan for each answer: yes, no, or a maybe that never firms up. The sheet asks what the client predicts the coworker will think and what they would think if the roles were reversed. After the ask, record what happened; a no is data, not a verdict.', '[{"id": "f0", "type": "textarea", "label": "The coworker I will ask, and why them:"}, {"id": "f1", "type": "textarea", "label": "The exact sentence, and the day I will say it:"}, {"id": "f2", "type": "textarea", "label": "What I predict they will think, and what I would think if they asked me:"}, {"id": "f3", "type": "textarea", "label": "My plan for a yes, a no, and a maybe that never firms up:"}, {"id": "f4", "type": "textarea", "label": "What happened, and what I make of it:"}]'::jsonb, array['social anxiety', 'exposure', 'connection']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('my-voice-shook-so-everyone-thinks-i-am-weak-thought-record', 'My Voice Shook So Everyone Thinks I Am Weak Thought Record', 'cbt'::resource_kind, 'A thought record for the shaky voice in a meeting or toast and the judgment the client assumes everyone made.', 'Use it to check the mind-reading and the catastrophe attached to a visible sign of nerves.', array['Adults', 'Teens']::text[], '15 minutes', 'Write the moment, the thought and its strength. Then ask: who actually commented, what the client thinks when someone else''s voice shakes, and how long they remembered the last time it happened to a colleague. Separate the sign of nerves from the meaning they gave it. The alternative thought can admit the voice shook; the question is only what that proves. Pair it with a plan to speak again soon rather than waiting for a steady voice.', '[{"id": "f0", "type": "textarea", "label": "The moment, and the thought about what everyone concluded:"}, {"id": "f1", "type": "textarea", "label": "Who actually said anything, and what they said:"}, {"id": "f2", "type": "textarea", "label": "What I think when someone else''s voice shakes:"}, {"id": "f3", "type": "textarea", "label": "How long I remembered the last colleague whose voice shook:"}, {"id": "f4", "type": "textarea", "label": "A thought that admits the shake and questions the verdict:"}]'::jsonb, array['social anxiety', 'thought record', 'thinking traps']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('social-mind-as-a-scorekeeper-who-only-counts-fumbles-page', 'Social Mind as a Scorekeeper Who Only Counts Fumbles Page', 'act'::resource_kind, 'A defusion page that casts the social mind as a scorekeeper who records every awkward pause and none of the ordinary good moments.', 'Use it to help a client see the one-sided tally without having to argue each entry.', array['Adults', 'Teens']::text[], '15 minutes', 'After a social event, the client writes what their scorekeeper recorded, then goes back through the same hour for what it skipped: the question they asked, the laugh they got, the person who sought them out. The exercise is not to balance the score but to notice the keeper''s bias and the fact that it is just a keeper. Practice naming it mid-event: there is the scorekeeper, back to the conversation. The page asks what happens to the fumbles when they are not the whole sheet.', '[{"id": "f0", "type": "textarea", "label": "What my scorekeeper recorded from the event:"}, {"id": "f1", "type": "textarea", "label": "What it skipped from the same hour:"}, {"id": "f2", "type": "textarea", "label": "What I notice about the kind of thing it counts:"}, {"id": "f3", "type": "textarea", "label": "A moment I named the scorekeeper mid-conversation, and what happened next:"}, {"id": "f4", "type": "textarea", "label": "What I want to be about at the next event, scorekeeper or no scorekeeper:"}]'::jsonb, array['social anxiety', 'defusion', 'metaphor']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('opposite-action-to-looking-at-the-phone-in-the-lobby-card', 'Opposite Action to Looking at the Phone in the Lobby Card', 'dbt'::resource_kind, 'An opposite action card for the waiting room or lobby where the phone comes out to avoid eye contact and small talk.', 'Use it to practice acting against the urge to hide in a low-stakes public space.', array['Adults', 'Teens']::text[], 'Five minutes in the next lobby', 'Identify the urge, which is to disappear into the screen, and the emotion under it. Then the opposite action, all the way: phone in the pocket, head up, posture open, eyes resting on the room, a nod or hello to one person if the moment comes. The card asks the client to stay that way for five minutes and record what happened and what the anxiety did. Nothing has to be said; the practice is the posture of being available.', '[{"id": "f0", "type": "textarea", "label": "Where I was, and what my urge was:"}, {"id": "f1", "type": "textarea", "label": "The opposite action all the way: what my body did for five minutes:"}, {"id": "f2", "type": "textarea", "label": "What my anxiety did over those minutes (0 to 10, start and end):"}, {"id": "f3", "type": "textarea", "label": "What actually happened in the room while I was available to it:"}, {"id": "f4", "type": "textarea", "label": "The next lobby I will practice in:"}]'::jsonb, array['social anxiety', 'opposite action', 'core DBT']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('question-ball-toss-answer-the-one-under-your-thumb-game', 'Question Ball Toss Answer the One Under Your Thumb Game', 'game'::resource_kind, 'A toss game with a ball covered in written questions; the catcher answers whichever question lands under their right thumb.', 'Use it to get a group talking in short turns with the randomness taking the pressure off.', array['Groups', 'Teens', 'Children']::text[], '20 minutes', 'Write twenty light questions on a beach ball or on tape wrapped around any ball: a food you hate, a place you would go tomorrow, a sound you love. Players toss it around the circle; the catcher reads the question under their right thumb, answers in one or two sentences, and tosses on. Any player may say pass once. After fifteen minutes, debrief: which question was the hardest to answer out loud, and what helped, such as the ball being the one that chose it.', '[{"id": "f0", "type": "textarea", "label": "The questions I answered, and what I said:"}, {"id": "f1", "type": "textarea", "label": "The question I would have passed on, and whether I did:"}, {"id": "f2", "type": "textarea", "label": "What made answering easier than it usually is for me:"}, {"id": "f3", "type": "textarea", "label": "Something I learned about another player:"}, {"id": "f4", "type": "textarea", "label": "Where in my week I could use the ball-chose-it attitude:"}]'::jsonb, array['social anxiety', 'group', 'game']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('telling-new-people-about-them-prepared-lines-sheet', 'Telling New People About Them Prepared Lines Sheet', 'worksheet'::resource_kind, 'Prepared lines for when a new acquaintance asks about the person the client lost, from a one-sentence version to a fuller one.', 'Use it to let a grieving client choose how much to say instead of being ambushed by the question.', array['Adults', 'Teens']::text[], '20 minutes', 'New jobs, new neighbors and new friends ask ordinary questions that land on the loss: do you have kids, is your mom nearby. Have the client write three versions of an answer, from a single true sentence to a paragraph, and decide which situations call for which. Add a line for changing the subject afterward and one for when they want to say more. The sheet is about the client''s control of the telling, not about getting it right.', '[{"id": "f0", "type": "textarea", "label": "The questions that land on my loss, and how they usually catch me:"}, {"id": "f1", "type": "textarea", "label": "My one-sentence version:"}, {"id": "f2", "type": "textarea", "label": "My fuller version, for when I want to say more:"}, {"id": "f3", "type": "textarea", "label": "Which situations get which version:"}, {"id": "f4", "type": "textarea", "label": "How I move the conversation on afterward if I want to:"}]'::jsonb, array['grief and loss', 'communication', 'planning']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('enjoying-the-trip-they-planned-means-i-am-heartless-sheet', 'Enjoying the Trip They Planned Means I Am Heartless Sheet', 'cbt'::resource_kind, 'A check sheet for the guilt of enjoying a trip, meal or event the person who died had planned or would have loved.', 'Use it to let a client hold enjoyment and grief in the same week without a verdict on their heart.', array['Adults', 'Teens']::text[], '20 minutes', 'Write the moment of enjoyment and the thought that followed. Ask what the person who died would have wanted for that moment, what enjoyment proves and does not prove about love, and what the client would say to a friend in the same seat. Let the grief stay in the room; the sheet is not about feeling less. Finish with a sentence that lets both be true. Expect tears; this one is for session, not homework.', '[{"id": "f0", "type": "textarea", "label": "The moment I enjoyed, and the thought that followed it:"}, {"id": "f1", "type": "textarea", "label": "What they would have wanted for that moment, as best I know:"}, {"id": "f2", "type": "textarea", "label": "What enjoying it proves about my love for them, and what it does not:"}, {"id": "f3", "type": "textarea", "label": "What I would say to a friend who felt this way:"}, {"id": "f4", "type": "textarea", "label": "A sentence that lets the enjoyment and the grief both be true:"}]'::jsonb, array['grief and loss', 'thinking traps', 'self-compassion']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('grief-as-a-record-that-skips-at-the-same-groove-page', 'Grief as a Record That Skips at the Same Groove Page', 'act'::resource_kind, 'An acceptance page that frames grief''s repeated return to one moment as a record skipping at the same groove, heard rather than fought.', 'Use it to help a client make room for the loop without believing it means they are failing to grieve properly.', array['Adults', 'Teens']::text[], '15 minutes', 'Many grieving clients return to one moment: the phone call, the last visit, the thing unsaid. Have them name the groove without replaying it in detail, then describe what they do when the record skips: slam the lid, play it louder, leave the room. The practice is to notice the skip, let the sound be there, and keep doing what the day asks. Grooves wear with time; the page asks what the record has sounded like over a month, not whether the skip has gone.', '[{"id": "f0", "type": "textarea", "label": "The groove my grief skips back to, named without replaying it:"}, {"id": "f1", "type": "textarea", "label": "What I usually do when the record skips:"}, {"id": "f2", "type": "textarea", "label": "What it is like to let the sound be there and keep going with the day:"}, {"id": "f3", "type": "textarea", "label": "Where I noticed the skip this week, and what I was able to do anyway:"}, {"id": "f4", "type": "textarea", "label": "What the record has sounded like over the last month:"}]'::jsonb, array['grief and loss', 'acceptance', 'metaphor']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('self-soothe-with-the-recipe-they-always-made-card', 'Self-Soothe With the Recipe They Always Made Card', 'dbt'::resource_kind, 'A self-soothe card built around cooking the dish the person who died always made, with the senses as the anchor.', 'Use it to give a grieving client a soothing ritual that includes the person rather than avoiding them.', array['Adults', 'Teens']::text[], 'One evening', 'The client chooses the dish, gathers what it needs, and cooks it slowly with attention on smell, sound, texture and taste, letting memories come and go without chasing them. The card asks what each sense brought up and whether the client ate it alone or shared it. Some clients cannot do this yet; a smaller version is one ingredient on the counter. Watch for the ritual becoming a test of whether they got the recipe right; the point is the senses, not the dish.', '[{"id": "f0", "type": "textarea", "label": "The dish, and why that one:"}, {"id": "f1", "type": "textarea", "label": "What each sense brought up while I cooked: smell, sound, touch, taste:"}, {"id": "f2", "type": "textarea", "label": "Memories that came, and what I did when they got loud:"}, {"id": "f3", "type": "textarea", "label": "Whether I ate it alone or with someone, and how that was:"}, {"id": "f4", "type": "textarea", "label": "Whether I would do this again, and when:"}]'::jsonb, array['grief and loss', 'self-soothing', 'core DBT']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('their-favorite-animal-clay-figure-craft', 'Their Favorite Animal Clay Figure Craft', 'kids'::resource_kind, 'A craft in which the child shapes the favorite animal of the person who died out of air-dry clay and decides where it lives.', 'Use it to give a grieving child a way to make something for the person with their hands.', array['Children']::text[], '40 minutes plus drying', 'The child and parent talk about the animal the person loved, then the child shapes it from air-dry clay, however rough. While they work the parent tells one story about the person and the animal, and asks the child for one. Once dry the child paints it and picks a spot: a shelf, a windowsill, the grave. The parent follows the child''s lead on how much to talk and lets silence be fine. If the figure breaks, that is a chance to talk about mending.', '[{"id": "f0", "type": "textarea", "label": "The animal I made, and why they loved it:"}, {"id": "f1", "type": "textarea", "label": "The story my grown-up told while I worked:"}, {"id": "f2", "type": "textarea", "label": "The story I told:"}, {"id": "f3", "type": "textarea", "label": "Where my clay animal lives now:"}, {"id": "f4", "type": "textarea", "label": "What I want to say to the person when I look at it:"}]'::jsonb, array['grief and loss', 'children', 'craft']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('group-trip-planning-when-one-friend-takes-over-sheet', 'Group Trip Planning When One Friend Takes Over Sheet', 'worksheet'::resource_kind, 'A sheet for the group trip where one friend has quietly become the planner-in-chief and the client is swallowing their preferences.', 'Use it to help a client name what they want from the trip and one way to say it before the itinerary is locked.', array['Adults', 'Teens']::text[], '20 minutes', 'Have the client list what has already been decided and by whom, what they actually want from the trip, and what they have swallowed so far to keep the peace. Then pick the one preference that matters most and draft a message to the group, not to the planner alone, that proposes it plainly. The sheet asks what the client fears will happen if they speak and what the trip will be like if they do not. Resentment on vacation is expensive.', '[{"id": "f0", "type": "textarea", "label": "What has been decided so far, and by whom:"}, {"id": "f1", "type": "textarea", "label": "What I actually want from this trip:"}, {"id": "f2", "type": "textarea", "label": "What I have swallowed so far to keep the peace:"}, {"id": "f3", "type": "textarea", "label": "The one preference I will raise, and my message to the group:"}, {"id": "f4", "type": "textarea", "label": "What I fear will happen if I speak, and what the trip looks like if I do not:"}]'::jsonb, array['relationship issues', 'assertiveness', 'planning']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('they-changed-the-subject-so-they-do-not-care-thought-record', 'They Changed the Subject So They Do Not Care Thought Record', 'cbt'::resource_kind, 'A thought record for the moment a friend or partner changes the subject and the client decides their news did not matter.', 'Use it to examine the leap from a conversational turn to a verdict on the relationship.', array['Adults', 'Teens']::text[], '15 minutes', 'Write the exchange as closely as the client can recall: what they said, what the other person said next, and the thought. Then list other reasons people change the subject, including discomfort, distraction and not knowing what to say. Ask whether the client has ever changed the subject on someone they love. Finish with an alternative and, if the topic still matters, a line for bringing it back up rather than filing the hurt.', '[{"id": "f0", "type": "textarea", "label": "What I said, and what they said next:"}, {"id": "f1", "type": "textarea", "label": "The thought I had about what the change of subject meant:"}, {"id": "f2", "type": "textarea", "label": "Other reasons people change the subject, including times I have done it:"}, {"id": "f3", "type": "textarea", "label": "An alternative reading of the moment:"}, {"id": "f4", "type": "textarea", "label": "If it still matters to me, how I will bring it back up:"}]'::jsonb, array['relationship issues', 'thought record', 'communication']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('being-right-as-a-trophy-that-costs-the-evening-page', 'Being Right as a Trophy That Costs the Evening Page', 'act'::resource_kind, 'A values page for the argument the client wins at the cost of the night, weighing the trophy against what they wanted the evening to be.', 'Use it to help a client choose between being right and being close when the two pull apart.', array['Adults', 'Teens']::text[], '15 minutes', 'Take a recent argument the client won or tried to win. Ask what the trophy was, what it cost, and what they would have wanted the evening to be about if they had not been competing. Then ask what being right protects for them; there is usually something underneath, like fairness or not being dismissed. The page ends with a choice point for the next argument: trophy or evening, said in the client''s own words. It does not ask them to be wrong.', '[{"id": "f0", "type": "textarea", "label": "The argument, and the trophy I was after:"}, {"id": "f1", "type": "textarea", "label": "What winning or trying to win cost that evening:"}, {"id": "f2", "type": "textarea", "label": "What I would have wanted the evening to be about:"}, {"id": "f3", "type": "textarea", "label": "What being right protects for me, underneath:"}, {"id": "f4", "type": "textarea", "label": "My choice point for next time, in my own words:"}]'::jsonb, array['relationship issues', 'values', 'conflict']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('validation-for-the-friend-whose-choice-i-disagree-with-card', 'Validation for the Friend Whose Choice I Disagree With Card', 'dbt'::resource_kind, 'A validation card for staying close to a friend who is making a choice the client thinks is a mistake, without endorsing it or lecturing.', 'Use it to help a client separate validating a feeling from approving a decision.', array['Adults', 'Teens']::text[], 'Ten minutes', 'Walk through the levels: paying attention, reflecting back, naming what makes sense about the feeling behind the choice, and being genuine. The card asks the client to write the sentence that validates the friend''s feeling without agreeing with the plan, and to notice the urge to add a but. Then decide whether to say the disagreement once, plainly, and let it rest. Clients who cannot find anything valid in the feeling are usually still arguing with the plan.', '[{"id": "f0", "type": "textarea", "label": "My friend''s choice, and what I think about it:"}, {"id": "f1", "type": "textarea", "label": "The feeling behind their choice that I can understand:"}, {"id": "f2", "type": "textarea", "label": "A sentence that validates that feeling without endorsing the plan:"}, {"id": "f3", "type": "textarea", "label": "The but I wanted to add, and what I will do with it:"}, {"id": "f4", "type": "textarea", "label": "Whether I will say my disagreement once, and how:"}]'::jsonb, array['relationship issues', 'interpersonal effectiveness', 'validation']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('friend-group-invitation-both-or-neither-pact-for-partners', 'Friend Group Invitation Both or Neither Pact for Partners', 'couples'::resource_kind, 'A pact for the friend group that invites one partner and not the other: when they go together, when one goes alone, and how the other hears.', 'Use it to stop a recurring invitation from becoming a recurring fight.', array['Couples']::text[], '25 minutes', 'Each partner describes the invitations in question and what they feel when they arrive: left out, obligated, relieved. Then agree on categories: events they attend together, events one attends alone with the other''s blessing, and events they decline. Add how the one who stays home wants to hear about it afterward, and how the one who goes wants to be greeted. Watch for the pact being a way to control the other''s friendships; the categories must be agreed by both.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the invitations I mean, and what I feel when they come:"}, {"id": "f1", "type": "textarea", "label": "Partner B: the invitations I mean, and what I feel when they come:"}, {"id": "f2", "type": "textarea", "label": "Events we go to together, events one of us goes to alone, events we decline:"}, {"id": "f3", "type": "textarea", "label": "How the one at home wants to hear about it afterward:"}, {"id": "f4", "type": "textarea", "label": "How the one who went wants to be greeted:"}]'::jsonb, array['relationship issues', 'couples', 'boundaries']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('crowded-concert-standing-area-spacing-plan-sheet', 'Crowded Concert Standing Area Spacing Plan Sheet', 'worksheet'::resource_kind, 'A plan for a standing-room concert where bodies press in from every side, with position, companions and an exit chosen in advance.', 'Use it to let a client go to the event they want to go to with a plan for the crowd.', array['Adults', 'Teens']::text[], '20 minutes', 'Map the space from what the client knows: where the edges are, where the exits are, and where they could stand with a wall or a friend at their back. Agree on who comes and what they know to do if the client taps them, a word for let''s move, and what the client will do with the first wave of tightness. Keep the plan on the practical and the stabilizing side; this is about attending with support, not about testing how much pressing they can stand.', '[{"id": "f0", "type": "textarea", "label": "Where I will stand, and what will be at my back:"}, {"id": "f1", "type": "textarea", "label": "Who is coming, and what they know to do if I tap them:"}, {"id": "f2", "type": "textarea", "label": "Our word for let''s move, and where we move to:"}, {"id": "f3", "type": "textarea", "label": "What I will do with the first wave of tightness:"}, {"id": "f4", "type": "textarea", "label": "How I will know it is time to leave, and how I will get out:"}, {"id": "f5", "type": "textarea", "label": "What I want from the night, in my own words:"}]'::jsonb, array['sexual abuse', 'safety', 'planning']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('enjoying-safe-touch-now-means-something-is-wrong-check-sheet', 'Enjoying Safe Touch Now Means Something Is Wrong Check Sheet', 'cbt'::resource_kind, 'A gentle check for the belief that wanting or enjoying safe touch now is a sign of something wrong, after what happened.', 'Use it to let a client examine a confusing guilt without reliving anything.', array['Adults', 'Teens']::text[], '20 minutes, in session', 'Write the belief as the client holds it and the ordinary moment that brought it up: a hug, a hand held, a partner''s touch they liked. Do not go near the past event itself. Look at what the belief assumes about pleasure and consent, what the client would say to another survivor who enjoyed a safe embrace, and what they know about bodies responding to safety. The alternative is theirs to write. Go slowly, and stop if the client moves toward the details of what happened.', '[{"id": "f0", "type": "textarea", "label": "The belief, and the safe moment that brought it up:"}, {"id": "f1", "type": "textarea", "label": "What the belief assumes about wanting touch:"}, {"id": "f2", "type": "textarea", "label": "What I would say to someone else who went through something and enjoyed a safe hug:"}, {"id": "f3", "type": "textarea", "label": "What I know about how bodies respond to safety:"}, {"id": "f4", "type": "textarea", "label": "A sentence about the touch I choose now, in my own words:"}]'::jsonb, array['sexual abuse', 'thinking traps', 'self-compassion']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('my-body-as-a-home-i-am-moving-back-into-page', 'My Body as a Home I Am Moving Back Into Page', 'act'::resource_kind, 'A values page that frames the client''s body as a home they are moving back into one room at a time, at their own pace.', 'Use it to give a client a gentle frame for reinhabiting the body without pressure to do it all at once.', array['Adults', 'Teens']::text[], '15 minutes', 'Some survivors describe living beside their body rather than in it. The page asks which rooms feel lived in already, such as the hands or the feet, which are still closed, and which one they might open a crack this week with something kind: a warm bath for the shoulders, lotion on the hands, a walk for the legs. Nothing is forced open. Keep to the stabilizing side and the present moment; this is about moving in, not about what happened in the house.', '[{"id": "f0", "type": "textarea", "label": "The rooms of my body I already live in:"}, {"id": "f1", "type": "textarea", "label": "The rooms that are still closed, named without going in:"}, {"id": "f2", "type": "textarea", "label": "One room I might open a crack this week, and the kind thing I will do there:"}, {"id": "f3", "type": "textarea", "label": "What I will do if a room feels like too much:"}, {"id": "f4", "type": "textarea", "label": "What living in my body a little more would let me do:"}]'::jsonb, array['sexual abuse', 'values', 'grounding']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('observe-the-chair-supporting-my-back-grounding-card', 'Observe the Chair Supporting My Back Grounding Card', 'dbt'::resource_kind, 'A grounding card that puts attention on the chair holding the client''s back and legs, used at the first sign of drifting.', 'Use it to give a client a fast, discreet way back into the room.', array['Adults', 'Teens']::text[], 'Two minutes', 'Teach it in session: notice the chair against the back, the seat under the thighs, the feet on the floor, and describe each in a few words without judgment. Then press the back into the chair and feel it hold. The card asks the client to practice it twice a day while calm so it is available when they drift. It is discreet enough for a meeting or a bus. Watch for the client who rushes through the list; the point is the support, not the inventory.', '[{"id": "f0", "type": "textarea", "label": "Where I practiced today, and what the chair felt like against my back:"}, {"id": "f1", "type": "textarea", "label": "The words I used to describe the seat and the floor:"}, {"id": "f2", "type": "textarea", "label": "How far away I was when I started, and where I was by the end:"}, {"id": "f3", "type": "textarea", "label": "What pressing my back into the chair did:"}, {"id": "f4", "type": "textarea", "label": "Where I could use this that nobody would notice:"}]'::jsonb, array['sexual abuse', 'grounding', 'core DBT']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('safe-touch-unsafe-touch-hand-tracing-craft', 'Safe Touch Unsafe Touch Hand Tracing Craft', 'kids'::resource_kind, 'A craft in which the child traces both hands, fills one with touches that are okay and one with touches that are not, and names who to tell.', 'Use it to give a child plain words for the touch rules and the grown-ups who keep them.', array['Children']::text[], '25 minutes', 'The child traces both hands on paper. In one hand they draw or write touches that are okay, like a high five or a hug they asked for; in the other, touches that are not okay or that feel uh-oh, in their own words. On each finger of the okay hand they write a safe grown-up to tell. The parent reviews it with them and says the rule aloud: no secrets about touch, and telling is always right. If a child discloses during this, stop the craft and follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Touches that are okay, in my okay hand:"}, {"id": "f1", "type": "textarea", "label": "Touches that are not okay or feel uh-oh, in my other hand:"}, {"id": "f2", "type": "textarea", "label": "The five grown-ups I can tell, one on each finger:"}, {"id": "f3", "type": "textarea", "label": "The rule my grown-up and I said out loud:"}, {"id": "f4", "type": "textarea", "label": "A question I still have about the rules:"}]'::jsonb, array['sexual abuse', 'children', 'craft', 'safety']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('coping-skill-pairings-two-that-work-together-sheet', 'Coping Skill Pairings Two That Work Together Sheet', 'worksheet'::resource_kind, 'A sheet for pairing coping skills that work better in sequence, such as a body skill first and a thinking skill second, tested over a week.', 'Use it to help a client who finds single skills too weak build a two-step combination.', array['Adults', 'Teens']::text[], '20 minutes, then one week', 'List the skills the client already uses and sort them into body-first skills, such as cold water or paced breathing, and mind skills, such as a thought check or a values question. Then build three pairs: one body skill that opens the door and one mind skill that walks through it. The client tests one pair per hard moment this week and rates the pair against the single skill. Watch for pairs of two thinking skills; the body usually has to go first.', '[{"id": "f0", "type": "textarea", "label": "My body-first skills, and my mind skills:"}, {"id": "f1", "type": "textarea", "label": "Three pairs I will test, body skill first then mind skill:"}, {"id": "f2", "type": "textarea", "label": "Each hard moment this week: the pair I used, and how it went (0 to 10):"}, {"id": "f3", "type": "textarea", "label": "How the pair compared with using one skill alone:"}, {"id": "f4", "type": "textarea", "label": "The pair I will keep as my default:"}]'::jsonb, array['coping skills', 'skills', 'planning']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('if-i-feel-worse-first-the-skill-is-wrong-belief-sheet', 'If I Feel Worse First the Skill Is Wrong Belief Sheet', 'cbt'::resource_kind, 'A belief sheet for the client who abandons a coping skill the moment it makes them more aware of the feeling before it eases.', 'Use it to examine the expectation that a skill should feel better from the first second.', array['Adults', 'Teens']::text[], '15 minutes', 'Write the belief and the skill the client quit. Then look at what happens in the first minute of paying attention to a feeling instead of away from it, and at other things in life that feel worse before better: a cold pool, a hard conversation, a stretch. Ask how long they gave the skill and what a fair trial would be. The alternative belief should allow for the dip and name the time they will give the skill before judging it.', '[{"id": "f0", "type": "textarea", "label": "The belief, and the skill I quit because of it:"}, {"id": "f1", "type": "textarea", "label": "What happens in the first minute when I turn toward a feeling instead of away:"}, {"id": "f2", "type": "textarea", "label": "Other things in my life that feel worse before they feel better:"}, {"id": "f3", "type": "textarea", "label": "How long I gave the skill, and what a fair trial would be:"}, {"id": "f4", "type": "textarea", "label": "An alternative belief that allows for the dip:"}]'::jsonb, array['coping skills', 'thinking traps', 'skills']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('coping-skill-as-a-paddle-not-an-anchor-page', 'Coping Skill as a Paddle Not an Anchor Page', 'act'::resource_kind, 'A metaphor page that frames a coping skill as a paddle for steering through rough water rather than an anchor that stops the boat.', 'Use it to help a client use skills to keep moving toward what matters rather than to freeze in place.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask the client which of their skills they use as anchors, to stop everything until the feeling passes, and which as paddles, to keep moving while the feeling is in the boat. Both have a place; the page asks what the anchor skills have cost in missed outings and conversations. Then they pick one situation this week to paddle through with a skill in hand instead of dropping anchor, and name where they are paddling toward. The water does not have to be calm first.', '[{"id": "f0", "type": "textarea", "label": "My skills I use as anchors, and my skills I use as paddles:"}, {"id": "f1", "type": "textarea", "label": "What dropping anchor has cost me recently:"}, {"id": "f2", "type": "textarea", "label": "One situation this week I will paddle through instead:"}, {"id": "f3", "type": "textarea", "label": "Where I am paddling toward, in my own words:"}, {"id": "f4", "type": "textarea", "label": "What happened in the boat while I paddled:"}]'::jsonb, array['coping skills', 'metaphor', 'committed action']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('accepts-contributing-by-holding-the-door-for-ten-people-card', 'ACCEPTS Contributing by Holding the Door for Ten People Card', 'dbt'::resource_kind, 'An ACCEPTS contributing card: hold a door, carry a bag or let a car merge ten times in a day, a distraction with a direction.', 'Use it to give a client a small outward-facing distraction for a day of rumination.', array['Adults', 'Teens']::text[], 'One day', 'Teach contributing as a way to turn attention from the loop to another person for a moment. The task is ten small contributions in one day, counted on the card: doors held, carts returned, a merge allowed, a compliment given. The client notes what the rumination did each time and what the other person did. Watch for the client who turns the count into a test of their goodness; the point is the direction of attention, not the moral score.', '[{"id": "f0", "type": "textarea", "label": "My ten contributions, counted through the day:"}, {"id": "f1", "type": "textarea", "label": "What the loop in my head did each time I did one:"}, {"id": "f2", "type": "textarea", "label": "What the other person did, if anything:"}, {"id": "f3", "type": "textarea", "label": "How the day compared with a day I spend inside the loop:"}, {"id": "f4", "type": "textarea", "label": "The contribution I will keep doing without counting:"}]'::jsonb, array['coping skills', 'distress tolerance', 'ACCEPTS']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('coping-skill-hot-and-cold-hidden-card-hunt-game', 'Coping Skill Hot and Cold Hidden Card Hunt Game', 'game'::resource_kind, 'A hunt game in which hidden coping skill cards are found with the group calling hot and cold, and each found skill is demonstrated.', 'Use it to get a group moving, cooperating and rehearsing skills in one round.', array['Groups', 'Children', 'Teens']::text[], '25 minutes', 'Hide eight cards, each naming a coping skill, around the room. One seeker at a time is guided by the group calling hot or cold until a card is found; the seeker reads it and leads the whole group in doing the skill for thirty seconds. Rotate seekers until all cards are found. Debrief on which skill was easiest to lead, which the group did not want to do, and what it was like to be guided by voices rather than finding it alone.', '[{"id": "f0", "type": "textarea", "label": "The card I found, and how the group led me to it:"}, {"id": "f1", "type": "textarea", "label": "What it was like to lead the group in the skill:"}, {"id": "f2", "type": "textarea", "label": "The skill the group did not want to do, and why I think that was:"}, {"id": "f3", "type": "textarea", "label": "The skill I found that I would actually use:"}, {"id": "f4", "type": "textarea", "label": "What being guided by the group was like compared with searching alone:"}]'::jsonb, array['coping skills', 'group', 'game']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('riding-the-subway-underground-tunnel-step-plan-sheet', 'Riding the Subway Underground Tunnel Step Plan Sheet', 'worksheet'::resource_kind, 'A step plan for riding an underground train, from standing on the platform to riding one stop to riding through the longest tunnel.', 'Use it to build a client''s approach to the subway in steps they choose and rate.', array['Adults', 'Teens']::text[], '20 minutes, then several weeks', 'Have the client list every step between where they are now and the ride they want to make, rated from zero to one hundred for expected fear: watching trains from the platform, boarding and stepping off before the doors close, one stop above ground, one stop underground, the long tunnel. They start at a step around forty and stay until the fear drops by half before moving on. The sheet tracks each attempt. The client decides the pace; the steps are theirs.', '[{"id": "f0", "type": "textarea", "label": "The ride I want to be able to make:"}, {"id": "f1", "type": "textarea", "label": "My steps from here to there, each rated 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "The step I will start with this week:"}, {"id": "f3", "type": "textarea", "label": "Each attempt: the step, the fear at the start and end, and how long I stayed:"}, {"id": "f4", "type": "textarea", "label": "What I noticed that my fear did not predict:"}]'::jsonb, array['phobias', 'exposure', 'planning']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('the-needle-will-break-off-in-my-arm-prediction-sheet', 'The Needle Will Break Off in My Arm Prediction Sheet', 'cbt'::resource_kind, 'A prediction sheet for the fear that a needle will snap or go wrong during a shot, tested against what the client knows and sees.', 'Use it to put a vivid fear next to the facts before the next appointment.', array['Adults', 'Teens']::text[], '15 minutes', 'Write the prediction and the certainty. Then gather what the client knows: how many injections they and the people they know have had, how many went the way the prediction says, and what the person giving the shot does to make the odds what they are. Set up the appointment as an experiment with the prediction written first. Afterward, record the result and the new certainty. If the client tends to faint at needles, add a tensing plan rather than relaxation.', '[{"id": "f0", "type": "textarea", "label": "The prediction, and how certain I am (0 to 100):"}, {"id": "f1", "type": "textarea", "label": "Injections I and people I know have had, and how many went this way:"}, {"id": "f2", "type": "textarea", "label": "What the person giving the shot does that the prediction leaves out:"}, {"id": "f3", "type": "textarea", "label": "What actually happened at the appointment:"}, {"id": "f4", "type": "textarea", "label": "My certainty now, and what I will carry to the next one:"}]'::jsonb, array['phobias', 'predictions', 'behavioral experiment']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('willing-to-let-the-bird-land-on-the-feeder-beside-me-page', 'Willing to Let the Bird Land on the Feeder Beside Me Page', 'act'::resource_kind, 'A willingness page for sitting near a bird feeder while birds come and go, making room for the flinch rather than waiting for it to leave.', 'Use it to help a client with a fear of birds stay in the garden on purpose.', array['Adults', 'Teens', 'Children']::text[], '15 minutes, then several sittings', 'Pick a spot a few yards from a feeder and a length of time the client agrees to stay. The page asks them to name the flinch when a bird lands, where it sits in the body, and what the mind says, and then to make room for all of it while the bird eats. Each sitting moves the chair a little closer if the client chooses. Willingness is not comfort; make that plain or they will think they are doing it wrong when the flinch comes.', '[{"id": "f0", "type": "textarea", "label": "Where I sat, how far from the feeder, and how long I agreed to stay:"}, {"id": "f1", "type": "textarea", "label": "What the flinch felt like when a bird landed, and where it sat in my body:"}, {"id": "f2", "type": "textarea", "label": "What my mind said, and what I did with that:"}, {"id": "f3", "type": "textarea", "label": "What the birds actually did while I made room for the flinch:"}, {"id": "f4", "type": "textarea", "label": "Where I will put the chair next time:"}]'::jsonb, array['phobias', 'willingness', 'exposure']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('cope-ahead-imagery-for-the-blood-pressure-cuff-squeeze-card', 'Cope Ahead Imagery for the Blood Pressure Cuff Squeeze Card', 'dbt'::resource_kind, 'A cope ahead card for the blood pressure cuff tightening, which some clients dread more than the needle.', 'Use it to rehearse the squeeze and the skills for it before the appointment.', array['Adults', 'Teens']::text[], '15 minutes', 'Describe the moment in detail: the cuff going on, the pump, the tightening, the thirty seconds of pressure, the release. Name the feelings and the thoughts that usually come, such as trapped or it will not stop. Choose the skills for each second of it: paced breathing before the pump, a grounding phrase during the squeeze, willing hands open on the lap. Rehearse in imagination twice, including one version where the nurse has to repeat it. Record what matched afterward.', '[{"id": "f0", "type": "textarea", "label": "The moment in detail, from the cuff going on to the release:"}, {"id": "f1", "type": "textarea", "label": "The feelings and thoughts I expect at the tightest point:"}, {"id": "f2", "type": "textarea", "label": "The skill for each part: before, during, and after:"}, {"id": "f3", "type": "textarea", "label": "How the rehearsal went, including the repeat-reading version:"}, {"id": "f4", "type": "textarea", "label": "After the real one: what matched, and what I did well:"}]'::jsonb, array['phobias', 'distress tolerance', 'cope ahead']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('brave-hedgehog-meets-the-doorbell-play', 'Brave Hedgehog Meets the Doorbell Play', 'kids'::resource_kind, 'A puppet play in which a brave hedgehog curls up at the doorbell, then learns to peek, then to wait by the door with the parent.', 'Use it to help a child who panics at the doorbell or a knock practice the steps through a character first.', array['Children']::text[], '20 minutes, then real doorbells', 'Make a hedgehog from a sock or a paper ball with toothpick spines. The parent rings a pretend bell and the hedgehog curls up; then the child helps the hedgehog try the next step each time: uncurl, peek, walk to the door with a grown-up, see who it is. Then swap and the child plays the hedgehog while the parent rings. Finally, plan a real doorbell with a known visitor. The parent names each brave step and never rings the real bell as a surprise.', '[{"id": "f0", "type": "textarea", "label": "What my hedgehog did at the first ring:"}, {"id": "f1", "type": "textarea", "label": "The steps my hedgehog tried: curl, peek, walk, look:"}, {"id": "f2", "type": "textarea", "label": "What I did when I played the hedgehog:"}, {"id": "f3", "type": "textarea", "label": "The real doorbell we planned, and who was behind it:"}, {"id": "f4", "type": "textarea", "label": "The brave step I want to try next:"}]'::jsonb, array['phobias', 'children', 'play']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('unfollow-and-mute-feed-cleanup-sheet', 'Unfollow and Mute Feed Cleanup Sheet', 'worksheet'::resource_kind, 'A sheet for going through the accounts the client follows and muting or unfollowing the ones that leave them picking at their appearance.', 'Use it to let a client change what their feed shows them in one sitting.', array['Adults', 'Teens']::text[], '30 minutes', 'Have the client scroll their feed for ten minutes in session and note each account that leaves them checking a mirror or a photo of themselves afterward, without arguing about whether it should. Then sort: mute, unfollow, or keep with a reason. Add three accounts to follow that have nothing to do with how anyone looks. The sheet asks what the feed felt like a week later. Keep the conversation away from any talk of bodies, shapes or sizes; it is about the feed''s effect.', '[{"id": "f0", "type": "textarea", "label": "Accounts that left me checking myself afterward:"}, {"id": "f1", "type": "textarea", "label": "What I did with each: mute, unfollow, or keep, and why:"}, {"id": "f2", "type": "textarea", "label": "Three accounts I added that have nothing to do with looks:"}, {"id": "f3", "type": "textarea", "label": "What my feed felt like a week later:"}, {"id": "f4", "type": "textarea", "label": "What I noticed about my mirror time over the week:"}]'::jsonb, array['body image', 'planning', 'self-monitoring']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('the-jacket-fits-differently-so-everyone-will-notice-record', 'The Jacket Fits Differently So Everyone Will Notice Record', 'cbt'::resource_kind, 'A thought record for the moment a piece of clothing fits differently and the client is certain everyone in the room will see it.', 'Use it to separate a clothing fact from the spotlight the client puts on it.', array['Adults', 'Teens']::text[], '15 minutes', 'Write the moment and the thought, and how strongly they believed it. Then look at the evidence: who actually said anything, what the client noticed about anyone else''s clothes that day, and how long they would remember another person''s jacket. Build an alternative that does not argue about the jacket, only about the audience. Keep the whole record away from the body itself and away from any plan to change it; the subject is attention, not fit.', '[{"id": "f0", "type": "textarea", "label": "The moment, and the thought about who would notice:"}, {"id": "f1", "type": "textarea", "label": "Who actually said anything, and what they said:"}, {"id": "f2", "type": "textarea", "label": "What I noticed about anyone else''s clothes that day:"}, {"id": "f3", "type": "textarea", "label": "How long I would remember someone else''s jacket:"}, {"id": "f4", "type": "textarea", "label": "An alternative thought about the audience, not the jacket:"}]'::jsonb, array['body image', 'thought record', 'thinking traps']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('body-as-the-library-not-the-cover-page', 'Body as the Library Not the Cover Page', 'act'::resource_kind, 'A metaphor page that frames the body as a library of what the client has lived, learned and loved, rather than the cover people judge.', 'Use it to move a client''s attention from how the body looks to what it holds and does.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask the client to list what their body has carried them through, learned to do, and held onto: the dance it knows, the recipes in its hands, the voice it has used for people it loves. That is the library. Then ask how much time the mind spends on the cover and what the shelves get in return. The page asks for one way this week to use the library on purpose. Keep all of it away from shape, size or any plan to alter the cover.', '[{"id": "f0", "type": "textarea", "label": "What my body has carried me through:"}, {"id": "f1", "type": "textarea", "label": "What my body knows how to do, and what it has learned:"}, {"id": "f2", "type": "textarea", "label": "How much of my attention goes to the cover, and what the shelves get:"}, {"id": "f3", "type": "textarea", "label": "One way I will use the library on purpose this week:"}, {"id": "f4", "type": "textarea", "label": "What I notice when I think of myself as the library:"}]'::jsonb, array['body image', 'metaphor', 'values']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('describe-not-judge-getting-dressed-in-the-dark-morning-card', 'Describe Not Judge Getting Dressed in the Dark Morning Card', 'dbt'::resource_kind, 'A describe-not-judge card for the early winter morning of getting dressed, replacing the mirror verdicts with plain descriptions.', 'Use it to practice the mindfulness what skill in the moment the judgments usually come fastest.', array['Adults', 'Teens']::text[], 'Five minutes each morning for a week', 'The client catches each judgment while dressing and replaces it with a description of what they are doing: pulling on a sweater, choosing the warmer socks, the light is still off. The card tracks the number of judgments caught and the one description that worked best. Do not aim for kind judgments; aim for none, just description. Keep the card off anything to do with the body''s shape or size; the words are about actions and the room.', '[{"id": "f0", "type": "textarea", "label": "Each morning: how many judgments I caught, roughly:"}, {"id": "f1", "type": "textarea", "label": "The descriptions I replaced them with:"}, {"id": "f2", "type": "textarea", "label": "The description that worked best:"}, {"id": "f3", "type": "textarea", "label": "What the mornings felt like by the end of the week:"}, {"id": "f4", "type": "textarea", "label": "Another time of day I could use describe-not-judge:"}]'::jsonb, array['body image', 'mindfulness', 'core DBT']::text[], '2026-11-28T15:00:00+00:00'::timestamptz),
  ('partners-compliment-i-argued-with-repair-talk-for-partners', 'Partner''s Compliment I Argued With Repair Talk for Partners', 'couples'::resource_kind, 'A repair talk for the moment one partner gives a compliment and the other disputes it, leaving both stung.', 'Use it to help a couple handle compliments so that giving one is not a risk and receiving one is not a fight.', array['Couples']::text[], '25 minutes', 'The partner who argues with compliments explains what happens inside when one lands and why disputing it feels necessary; the partner who gives them says what it is like to be contradicted. Agree on a receiving rule such as thank you and nothing else for a week, and a giving rule that compliments stay off appearance unless asked. Add a repair line for the next time one is argued with. Keep the talk clear of any commentary on bodies; the subject is the exchange.', '[{"id": "f0", "type": "textarea", "label": "Partner A (who argues with compliments): what happens inside me when one lands:"}, {"id": "f1", "type": "textarea", "label": "Partner B (who gives them): what it is like when my compliment is disputed:"}, {"id": "f2", "type": "textarea", "label": "Our receiving rule for the week:"}, {"id": "f3", "type": "textarea", "label": "Our giving rule, including what compliments stay off:"}, {"id": "f4", "type": "textarea", "label": "Our repair line for the next time one is argued with:"}]'::jsonb, array['body image', 'couples', 'repair']::text[], '2026-11-28T15:00:00+00:00'::timestamptz)
