-- Clinician library resources for 2026-11-28: five of every kind (worksheet, cbt, act, dbt,
-- couples, kids, game) and five on each of the eighteen daily topics, 125 rows in all.
-- Generated from data/therapist-resources.json by:
--   python3 tools/therapist_resources_sql.py --since 2026-11-28
-- An upsert on slug: applying it twice is harmless.
on conflict (slug) do update set
  title      = excluded.title,
  kind       = excluded.kind,
  summary    = excluded.summary,
  goal       = excluded.goal,
  audience   = excluded.audience,
  duration   = excluded.duration,
  body_md    = excluded.body_md,
  fields     = excluded.fields,
  tags       = excluded.tags,
  created_at = excluded.created_at;
